const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"frontend/src/components/admin/AdminTable.tsx":"\"use client\";\nimport { ReactNode } from \"react\";\n\nconst t = {\n  border: \"rgba(255,255,255,0.07)\",\n  text:   \"rgba(255,255,255,0.9)\",\n  muted:  \"rgba(255,255,255,0.4)\",\n  card:   \"rgba(255,255,255,0.03)\",\n};\n\n// Responsive stat card grid\nexport function StatGrid({ children, cols=4 }: { children:ReactNode; cols?:number }) {\n  return (\n    <>\n      <div style={{ display:\"grid\", gridTemplateColumns:`repeat(${cols},1fr)`, gap:12, marginBottom:24 }} className=\"adm-stat-grid\">\n        {children}\n      </div>\n      <style>{`\n        @media(max-width:900px){ .adm-stat-grid{ grid-template-columns:1fr 1fr!important; } }\n        @media(max-width:480px){ .adm-stat-grid{ gap:8px!important; } }\n      `}</style>\n    </>\n  );\n}\n\n// Stat card\nexport function StatCard({ label, value, color, icon:Icon, sub }: any) {\n  return (\n    <div style={{ padding:18, borderRadius:16, background:t.card, border:`1px solid ${t.border}` }}>\n      <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:14 }}>\n        <div style={{ width:34, height:34, borderRadius:10, background:`${color}14`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n          <Icon size={15} color={color}/>\n        </div>\n        {sub !== undefined && (\n          <span style={{ fontSize:10, fontWeight:700, padding:\"2px 8px\", borderRadius:99, background:sub>=0?\"rgba(16,185,129,0.1)\":\"rgba(239,68,68,0.1)\", color:sub>=0?\"#10B981\":\"#EF4444\" }}>\n            {sub>=0?\"+\":\"\"}{sub}%\n          </span>\n        )}\n      </div>\n      <p style={{ fontSize:22, fontWeight:900, color:t.text, letterSpacing:\"-0.05em\", margin:\"0 0 3px\", lineHeight:1 }}>{value}</p>\n      <p style={{ fontSize:11, color:t.muted, margin:0 }}>{label}</p>\n    </div>\n  );\n}\n\n// Badge pill\nexport function Badge({ label, color, bg }: { label:string; color:string; bg:string }) {\n  return (\n    <span style={{ fontSize:11, fontWeight:700, padding:\"3px 10px\", borderRadius:99, background:bg, color, display:\"inline-block\", whiteSpace:\"nowrap\" }}>\n      {label}\n    </span>\n  );\n}\n\n// Filter bar — wraps on mobile\nexport function FilterBar({ children }: { children:ReactNode }) {\n  return (\n    <>\n      <div style={{ display:\"flex\", gap:10, marginBottom:14, flexWrap:\"wrap\" }} className=\"adm-filter\">\n        {children}\n      </div>\n      <style>{`\n        @media(max-width:640px){ .adm-filter>div,.adm-filter>select,.adm-filter>input{ width:100%!important; flex:none!important; } }\n      `}</style>\n    </>\n  );\n}\n\n// Search input\nexport function SearchInput({ value, onChange, placeholder }: { value:string; onChange:(v:string)=>void; placeholder?:string }) {\n  return (\n    <div style={{ flex:1, minWidth:200, display:\"flex\", alignItems:\"center\", gap:8, padding:\"9px 14px\", borderRadius:12, background:\"rgba(255,255,255,0.04)\", border:`1px solid ${t.border}` }}>\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"rgba(255,255,255,0.4)\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"M21 21l-4.35-4.35\"/></svg>\n      <input value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder||\"Search...\"}\n        style={{ flex:1, background:\"transparent\", border:\"none\", outline:\"none\", color:t.text, fontSize:13, fontFamily:\"inherit\" }}/>\n    </div>\n  );\n}\n\n// Select filter\nexport function SelectFilter({ value, onChange, options }: { value:string; onChange:(v:string)=>void; options:{value:string;label:string}[] }) {\n  return (\n    <select value={value} onChange={e => onChange(e.target.value)}\n      style={{ padding:\"9px 14px\", borderRadius:12, border:`1px solid ${t.border}`, background:\"rgba(255,255,255,0.04)\", color:\"rgba(255,255,255,0.6)\", fontSize:13, fontFamily:\"inherit\", outline:\"none\", cursor:\"pointer\" }}>\n      {options.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}\n    </select>\n  );\n}\n\n// Page header\nexport function PageHeader({ title, sub, action }: { title:string; sub:string; action?:ReactNode }) {\n  return (\n    <div style={{ display:\"flex\", alignItems:\"flex-start\", justifyContent:\"space-between\", marginBottom:22, gap:12, flexWrap:\"wrap\" }}>\n      <div>\n        <h1 style={{ fontSize:\"clamp(18px,3vw,24px)\", fontWeight:900, letterSpacing:\"-0.04em\", color:t.text, margin:\"0 0 3px\" }}>{title}</h1>\n        <p style={{ fontSize:13, color:t.muted, margin:0 }}>{sub}</p>\n      </div>\n      {action && <div>{action}</div>}\n    </div>\n  );\n}\n\n// Pagination\nexport function Pagination({ page, pages, total, onPage }: { page:number; pages:number; total:number; onPage:(p:number)=>void }) {\n  if (!pages || pages <= 1) return null;\n  const range = Array.from({ length: Math.min(pages, 5) }, (_, i) => {\n    if (pages <= 5) return i + 1;\n    if (page <= 3) return i + 1;\n    if (page >= pages - 2) return pages - 4 + i;\n    return page - 2 + i;\n  }).filter(p => p >= 1 && p <= pages);\n\n  const btnStyle = (active: boolean): any => ({\n    minWidth:32, height:32, padding:\"0 10px\", borderRadius:8,\n    border:`1px solid ${active?\"rgba(107,53,232,0.5)\":\"rgba(255,255,255,0.07)\"}`,\n    background:active?\"rgba(107,53,232,0.15)\":\"transparent\",\n    color:active?\"#A78BFA\":\"rgba(255,255,255,0.4)\",\n    cursor:\"pointer\", fontSize:12, fontWeight:active?700:400,\n  });\n\n  return (\n    <div style={{ display:\"flex\", justifyContent:\"space-between\", alignItems:\"center\", marginTop:14, flexWrap:\"wrap\", gap:10 }}>\n      <span style={{ fontSize:12, color:\"rgba(255,255,255,0.3)\" }}>{(total||0).toLocaleString()} total</span>\n      <div style={{ display:\"flex\", gap:4, flexWrap:\"wrap\" }}>\n        <button onClick={() => onPage(page-1)} disabled={page===1} style={{ ...btnStyle(false), opacity:page===1?0.3:1 }}>←</button>\n        {range.map(p => <button key={p} onClick={() => onPage(p)} style={btnStyle(p===page)}>{p}</button>)}\n        <button onClick={() => onPage(page+1)} disabled={page>=pages} style={{ ...btnStyle(false), opacity:page>=pages?0.3:1 }}>→</button>\n      </div>\n    </div>\n  );\n}\n\n// Responsive data table — on mobile collapses to card-style rows\nexport function DataTable({ cols, rows, loading, empty=\"No records found\" }: {\n  cols: { key:string; label:string; width?:string; hide?:\"sm\"|\"md\" }[];\n  rows: { [key:string]:ReactNode }[];\n  loading?: boolean;\n  empty?:   string;\n}) {\n  const tplCols = cols.map(c => c.width || \"1fr\").join(\" \");\n  const hdrs    = cols.map(c => (\n    <span key={c.key} className={c.hide?`adm-col-hide-${c.hide}`:\"\"} style={{ fontSize:10, fontWeight:700, letterSpacing:\"0.08em\", color:\"rgba(255,255,255,0.25)\", textTransform:\"uppercase\" }}>\n      {c.label}\n    </span>\n  ));\n\n  return (\n    <div style={{ borderRadius:16, border:`1px solid ${t.border}`, overflow:\"hidden\", overflowX:\"auto\" }}>\n      <div style={{ minWidth:480 }}>\n        <div style={{ display:\"grid\", gridTemplateColumns:tplCols, gap:0, padding:\"9px 16px\", background:\"rgba(255,255,255,0.02)\", borderBottom:`1px solid ${t.border}` }}>\n          {hdrs}\n        </div>\n        {loading ? (\n          <div style={{ padding:\"40px 0\", textAlign:\"center\", color:t.muted, fontSize:13 }}>Loading...</div>\n        ) : rows.length === 0 ? (\n          <div style={{ padding:\"40px 0\", textAlign:\"center\", color:t.muted, fontSize:13 }}>{empty}</div>\n        ) : rows.map((row, i) => (\n          <div key={i} style={{ display:\"grid\", gridTemplateColumns:tplCols, gap:0, padding:\"12px 16px\", borderBottom:`1px solid rgba(255,255,255,0.04)`, alignItems:\"center\" }}>\n            {cols.map(c => (\n              <div key={c.key} className={c.hide?`adm-col-hide-${c.hide}`:\"\"} style={{ overflow:\"hidden\", minWidth:0 }}>\n                {row[c.key]}\n              </div>\n            ))}\n          </div>\n        ))}\n      </div>\n      <style>{`\n        @media(max-width:768px){ .adm-col-hide-md{ display:none!important; } }\n        @media(max-width:540px){ .adm-col-hide-sm{ display:none!important; } }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/admin/layout.tsx":"\"use client\";\nimport { useEffect, useState } from \"react\";\nimport { useRouter, usePathname } from \"next/navigation\";\nimport Link from \"next/link\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport {\n  LayoutDashboard, Users, CreditCard, BarChart2, Settings,\n  AlertCircle, List, Clock, Zap, LogOut, Menu, X, ChevronRight,\n  Globe, Shield, Bell\n} from \"lucide-react\";\n\nconst V = { v500:\"#6B35E8\", v700:\"#3D1C8A\", v400:\"#8B5CF6\", v300:\"#A78BFA\" };\n\nconst NAV = [\n  { href:\"/admin\",           icon:LayoutDashboard, label:\"Overview\",   exact:true },\n  { href:\"/admin/users\",     icon:Users,           label:\"Users\"              },\n  { href:\"/admin/payments\",  icon:CreditCard,      label:\"Payments\"           },\n  { href:\"/admin/analytics\", icon:BarChart2,       label:\"Analytics\"          },\n  { href:\"/admin/waitlist\",  icon:List,            label:\"Waitlist\"           },\n  { href:\"/admin/support\",   icon:Bell,            label:\"Support\"            },\n  { href:\"/admin/audit-logs\",icon:Shield,          label:\"Audit Logs\"         },\n  { href:\"/admin/error-logs\",icon:AlertCircle,     label:\"Error Logs\"         },\n  { href:\"/admin/settings\",  icon:Settings,        label:\"Settings\"           },\n];\n\nexport default function AdminLayout({ children }: { children: React.ReactNode }) {\n  const { user, isHydrated, logout } = useAuthStore();\n  const router   = useRouter();\n  const pathname = usePathname();\n  const [open,   setOpen]   = useState(false);\n\n  useEffect(() => {\n    if (!isHydrated) return;\n    if (!user) { router.replace(\"/auth/login\"); return; }\n    if (user.role !== \"SUPER_ADMIN\") { router.replace(\"/dashboard\"); }\n  }, [user, isHydrated]);\n\n  if (!isHydrated || !user || user.role !== \"SUPER_ADMIN\") {\n    return (\n      <div style={{ minHeight:\"100vh\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", background:\"#07050F\" }}>\n        <div style={{ width:36, height:36, borderRadius:\"50%\", border:\"3px solid rgba(107,53,232,0.2)\", borderTopColor:V.v500, animation:\"spin 0.8s linear infinite\" }}/>\n        <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n      </div>\n    );\n  }\n\n  const isActive = (nav: any) => nav.exact ? pathname === nav.href : pathname.startsWith(nav.href);\n\n  const SidebarContent = () => (\n    <div style={{ display:\"flex\", flexDirection:\"column\", height:\"100%\", padding:\"20px 0\" }}>\n      {/* Logo */}\n      <div style={{ padding:\"0 16px 24px\", borderBottom:\"1px solid rgba(255,255,255,0.06)\" }}>\n        <Link href=\"/admin\" style={{ display:\"flex\", alignItems:\"center\", gap:10, textDecoration:\"none\" }}>\n          <div style={{ width:34, height:34, borderRadius:10, background:`linear-gradient(135deg,${V.v500},${V.v700})`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n            <Zap size={16} color=\"#fff\" fill=\"#fff\"/>\n          </div>\n          <div>\n            <p style={{ fontSize:14, fontWeight:900, color:\"#fff\", margin:0, letterSpacing:\"-0.03em\" }}>DropOS</p>\n            <p style={{ fontSize:10, color:\"rgba(255,255,255,0.35)\", margin:0, fontWeight:600 }}>ADMIN PANEL</p>\n          </div>\n        </Link>\n      </div>\n\n      {/* Nav */}\n      <nav style={{ flex:1, padding:\"16px 8px\", overflowY:\"auto\" }}>\n        {NAV.map(n => {\n          const active = isActive(n);\n          const Icon = n.icon;\n          return (\n            <Link key={n.href} href={n.href} onClick={()=>setOpen(false)}\n              style={{ display:\"flex\", alignItems:\"center\", gap:10, padding:\"9px 12px\", borderRadius:12, marginBottom:2, textDecoration:\"none\", background:active?`rgba(107,53,232,0.12)`:\"transparent\", border:`1px solid ${active?\"rgba(107,53,232,0.25)\":\"transparent\"}`, transition:\"all 0.15s\" }}>\n              <Icon size={15} color={active?V.v300:\"rgba(255,255,255,0.4)\"}/>\n              <span style={{ fontSize:13, fontWeight:600, color:active?\"#fff\":\"rgba(255,255,255,0.5)\" }}>{n.label}</span>\n              {active && <ChevronRight size={12} color={V.v300} style={{ marginLeft:\"auto\" }}/>}\n            </Link>\n          );\n        })}\n      </nav>\n\n      {/* User */}\n      <div style={{ padding:\"16px\", borderTop:\"1px solid rgba(255,255,255,0.06)\" }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:10 }}>\n          <div style={{ width:32, height:32, borderRadius:10, background:`linear-gradient(135deg,${V.v500},${V.v700})`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", fontSize:13, fontWeight:800, color:\"#fff\" }}>\n            {user.name?.charAt(0)||\"A\"}\n          </div>\n          <div style={{ flex:1, minWidth:0 }}>\n            <p style={{ fontSize:12, fontWeight:700, color:\"rgba(255,255,255,0.8)\", margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{user.name}</p>\n            <p style={{ fontSize:10, color:\"rgba(255,255,255,0.3)\", margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>Super Admin</p>\n          </div>\n        </div>\n        <div style={{ display:\"flex\", gap:6 }}>\n          <Link href=\"/dashboard\" style={{ flex:1, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:5, padding:\"7px\", borderRadius:8, background:\"rgba(255,255,255,0.04)\", border:\"1px solid rgba(255,255,255,0.06)\", textDecoration:\"none\", fontSize:11, fontWeight:600, color:\"rgba(255,255,255,0.4)\" }}>\n            <Globe size={11}/> Store\n          </Link>\n          <button onClick={()=>{logout();router.push(\"/auth/login\");}} style={{ flex:1, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:5, padding:\"7px\", borderRadius:8, background:\"rgba(239,68,68,0.08)\", border:\"1px solid rgba(239,68,68,0.15)\", cursor:\"pointer\", fontSize:11, fontWeight:600, color:\"rgba(239,68,68,0.7)\", fontFamily:\"inherit\" }}>\n            <LogOut size={11}/> Sign out\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n\n  return (\n    <div style={{ minHeight:\"100vh\", background:\"#07050F\", fontFamily:\"system-ui,sans-serif\", display:\"flex\" }}>\n      {/* Desktop sidebar */}\n      <aside style={{ width:220, flexShrink:0, background:\"rgba(255,255,255,0.02)\", borderRight:\"1px solid rgba(255,255,255,0.06)\", height:\"100vh\", position:\"sticky\", top:0, display:\"flex\", flexDirection:\"column\" }} className=\"hidden lg:flex\">\n        <SidebarContent/>\n      </aside>\n\n      {/* Mobile overlay */}\n      {open && (\n        <div style={{ position:\"fixed\", inset:0, zIndex:40, display:\"flex\" }}>\n          <div onClick={()=>setOpen(false)} style={{ flex:1, background:\"rgba(0,0,0,0.7)\", backdropFilter:\"blur(4px)\" }}/>\n          <div style={{ width:220, background:\"#0d0a1a\", borderLeft:\"1px solid rgba(255,255,255,0.06)\", height:\"100%\", display:\"flex\", flexDirection:\"column\" }}>\n            <SidebarContent/>\n          </div>\n        </div>\n      )}\n\n      {/* Main content */}\n      <div style={{ flex:1, display:\"flex\", flexDirection:\"column\", minWidth:0 }}>\n        {/* Mobile top bar */}\n        <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", padding:\"12px 16px\", borderBottom:\"1px solid rgba(255,255,255,0.06)\", position:\"sticky\", top:0, background:\"rgba(7,5,15,0.9)\", backdropFilter:\"blur(10px)\", zIndex:30 }} className=\"lg:hidden\">\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:10 }}>\n            <div style={{ width:28, height:28, borderRadius:8, background:`linear-gradient(135deg,${V.v500},${V.v700})`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n              <Zap size={13} color=\"#fff\" fill=\"#fff\"/>\n            </div>\n            <span style={{ fontSize:14, fontWeight:900, color:\"#fff\" }}>DropOS Admin</span>\n          </div>\n          <button onClick={()=>setOpen(o=>!o)} style={{ background:\"none\", border:\"none\", cursor:\"pointer\", color:\"rgba(255,255,255,0.5)\", padding:4 }}>\n            {open?<X size={20}/>:<Menu size={20}/>}\n          </button>\n        </div>\n\n        {/* Page content */}\n        <main style={{ flex:1, padding:\"clamp(16px,3vw,28px)\", overflowY:\"auto\" }}>\n      \n      <style>{`\n        :root {\n          --bg-base: #07050F;\n          --bg-card: rgba(255,255,255,0.03);\n          --bg-card-hover: rgba(255,255,255,0.05);\n          --border: rgba(255,255,255,0.07);\n          --text-primary: rgba(255,255,255,0.9);\n          --text-secondary: rgba(255,255,255,0.6);\n          --text-tertiary: rgba(255,255,255,0.35);\n          --accent: #6B35E8;\n          --accent-light: rgba(107,53,232,0.15);\n          --green: #10B981;\n          --amber: #F59E0B;\n          --red: #EF4444;\n        }\n      `}</style>\n          {children}\n        </main>\n      </div>\n\n      <style>{`\n        .lg\\\\:flex { display: flex !important; }\n        .lg\\\\:hidden { display: none !important; }\n        .hidden { display: none !important; }\n        @media(min-width:1024px) {\n          .lg\\\\:flex { display: flex !important; }\n          .lg\\\\:hidden { display: none !important; }\n          .hidden { display: flex !important; }\n        }\n        @media(max-width:1023px) {\n          .lg\\\\:flex { display: none !important; }\n          .lg\\\\:hidden { display: flex !important; }\n        }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/admin/page.tsx":"\"use client\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { adminAPI } from \"../../lib/api\";\nimport { AreaChart, Area, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from \"recharts\";\nimport { Users, DollarSign, ShoppingCart, TrendingUp, Store, Zap, ArrowUpRight, Activity, Clock, ChevronRight, AlertCircle } from \"lucide-react\";\nimport Link from \"next/link\";\n\nconst V = { v500:\"#6B35E8\", v700:\"#3D1C8A\", v400:\"#8B5CF6\", v300:\"#A78BFA\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\n\nfunction fmt(n: number) { return new Intl.NumberFormat(\"en-NG\",{style:\"currency\",currency:\"NGN\",maximumFractionDigits:0}).format(n||0); }\nfunction num(n: number) { return n>=1000000?`${(n/1000000).toFixed(1)}M`:n>=1000?`${(n/1000).toFixed(1)}k`:String(n||0); }\n\nfunction StatCard({ label, value, sub, color, icon:Icon, delay=0 }: any) {\n  return (\n    <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay}}\n      style={{ padding:20, borderRadius:16, background:\"rgba(255,255,255,0.03)\", border:\"1px solid rgba(255,255,255,0.06)\" }}>\n      <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:14 }}>\n        <div style={{ width:36, height:36, borderRadius:10, background:`${color}15`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n          <Icon size={16} color={color}/>\n        </div>\n        {sub !== undefined && (\n          <span style={{ fontSize:11, fontWeight:700, color:sub>=0?V.green:V.red, background:sub>=0?\"rgba(16,185,129,0.1)\":\"rgba(239,68,68,0.1)\", padding:\"2px 8px\", borderRadius:99 }}>\n            {sub>=0?\"+\":\"\"}{sub}%\n          </span>\n        )}\n      </div>\n      <p style={{ fontSize:24, fontWeight:900, color:\"#fff\", letterSpacing:\"-0.05em\", margin:\"0 0 4px\", lineHeight:1 }}>{value}</p>\n      <p style={{ fontSize:12, color:\"rgba(255,255,255,0.4)\", margin:0 }}>{label}</p>\n    </motion.div>\n  );\n}\n\nconst DEMO_REVENUE = [\n  {month:\"Jan\",revenue:1840000,fees:184000},{month:\"Feb\",revenue:2360000,fees:236000},\n  {month:\"Mar\",revenue:2890000,fees:289000},{month:\"Apr\",revenue:3520000,fees:352000},\n  {month:\"May\",revenue:4380000,fees:438000},{month:\"Jun\",revenue:5210000,fees:521000},\n  {month:\"Jul\",revenue:6140000,fees:614000},{month:\"Aug\",revenue:7200000,fees:720000},\n];\n\nconst DEMO_GW = [\n  {name:\"Paystack\",value:68,color:V.amber},\n  {name:\"Stripe\",  value:24,color:V.v400},\n  {name:\"Other\",   value:8, color:V.cyan},\n];\n\nexport default function AdminDashboard() {\n  const { data: stats, isLoading } = useQuery({\n    queryKey: [\"admin-overview\"],\n    queryFn: () => adminAPI.getStats().then(r => r.data.data),\n    refetchInterval: 60000,\n    retry: 2,\n  });\n\n  const { data: usersData } = useQuery({\n    queryKey: [\"admin-recent-users\"],\n    queryFn: () => adminAPI.getUsers({ limit:5, sort:\"newest\" }).then(r => r.data),\n    retry: 2,\n  });\n\n  const statCards = [\n    { label:\"Total Users\",       value: num(stats?.users?.total||0),       sub:stats?.users?.growth,       color:V.v400,  icon:Users         },\n    { label:\"Platform Revenue\",  value: fmt(stats?.revenue?.total||0),     sub:stats?.revenue?.growth,     color:V.green, icon:DollarSign    },\n    { label:\"Active Stores\",     value: num(stats?.stores?.active||0),     sub:stats?.stores?.growth,      color:V.cyan,  icon:Store         },\n    { label:\"Total Orders\",      value: num(stats?.orders?.total||0),      sub:stats?.orders?.growth,      color:V.amber, icon:ShoppingCart  },\n    { label:\"DropOS Fees\",       value: fmt(stats?.fees?.total||0),        sub:undefined,                  color:V.v300,  icon:TrendingUp    },\n    { label:\"Avg MRR per Store\", value: fmt(stats?.avgMRR||0),             sub:undefined,                  color:V.green, icon:Activity      },\n  ];\n\n  const recentUsers = usersData?.data || [];\n  const gwData = stats?.gatewayStats?.length ? stats.gatewayStats.map((g:any)=>({name:g.gateway,value:g._count?.id||0,color:g.gateway===\"PAYSTACK\"?V.amber:V.v400})) : DEMO_GW;\n  const revenueData = stats?.monthlyRevenue?.length ? stats.monthlyRevenue : DEMO_REVENUE;\n\n  return (\n    <div>\n      {/* Header */}\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{ marginBottom:24 }}>\n        <h1 style={{ fontSize:\"clamp(20px,4vw,26px)\", fontWeight:900, letterSpacing:\"-0.04em\", color:\"#fff\", margin:\"0 0 4px\" }}>Platform Overview</h1>\n        <p style={{ fontSize:13, color:\"rgba(255,255,255,0.35)\", margin:0 }}>\n          All merchants · {new Date().toLocaleDateString(\"en-NG\",{month:\"long\",year:\"numeric\"})}\n        </p>\n      </motion.div>\n\n      {/* Stat grid */}\n      <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(auto-fill,minmax(160px,1fr))\", gap:12, marginBottom:24 }}>\n        {statCards.map((s,i) => <StatCard key={s.label} {...s} delay={i*0.06}/>)}\n      </div>\n\n      {/* Charts row */}\n      <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 280px\", gap:16, marginBottom:20 }} className=\"admin-charts\">\n        {/* Revenue chart */}\n        <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.4}}\n          style={{ padding:20, borderRadius:16, background:\"rgba(255,255,255,0.03)\", border:\"1px solid rgba(255,255,255,0.06)\" }}>\n          <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:20, flexWrap:\"wrap\", gap:8 }}>\n            <p style={{ fontSize:14, fontWeight:700, color:\"#fff\", margin:0 }}>Platform Revenue</p>\n            <Link href=\"/admin/analytics\" style={{ display:\"flex\", alignItems:\"center\", gap:4, fontSize:12, color:V.v300, textDecoration:\"none\", fontWeight:600 }}>\n              Full report <ArrowUpRight size={12}/>\n            </Link>\n          </div>\n          <ResponsiveContainer width=\"100%\" height={200}>\n            <AreaChart data={revenueData} margin={{top:0,right:0,bottom:0,left:0}}>\n              <defs>\n                <linearGradient id=\"gr\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                  <stop offset=\"5%\" stopColor={V.v400} stopOpacity={0.2}/>\n                  <stop offset=\"95%\" stopColor={V.v400} stopOpacity={0}/>\n                </linearGradient>\n              </defs>\n              <XAxis dataKey=\"month\" tick={{fill:\"rgba(255,255,255,0.3)\",fontSize:10}} axisLine={false} tickLine={false}/>\n              <YAxis tick={{fill:\"rgba(255,255,255,0.3)\",fontSize:10}} axisLine={false} tickLine={false} tickFormatter={v=>`₦${(v/1000000).toFixed(1)}M`}/>\n              <Tooltip contentStyle={{background:\"#181230\",border:\"1px solid rgba(107,53,232,0.3)\",borderRadius:10,fontSize:12}} formatter={(v:any)=>[fmt(v),\"Revenue\"]}/>\n              <Area type=\"monotone\" dataKey=\"revenue\" stroke={V.v400} strokeWidth={2} fill=\"url(#gr)\"/>\n            </AreaChart>\n          </ResponsiveContainer>\n        </motion.div>\n\n        {/* Gateway pie */}\n        <motion.div initial={{opacity:0,x:16}} animate={{opacity:1,x:0}} transition={{delay:0.45}}\n          style={{ padding:20, borderRadius:16, background:\"rgba(255,255,255,0.03)\", border:\"1px solid rgba(255,255,255,0.06)\" }}>\n          <p style={{ fontSize:14, fontWeight:700, color:\"#fff\", margin:\"0 0 16px\" }}>Payment Gateways</p>\n          <div style={{ display:\"flex\", justifyContent:\"center\" }}>\n            <PieChart width={140} height={140}>\n              <Pie data={gwData} cx={65} cy={65} innerRadius={38} outerRadius={60} dataKey=\"value\" strokeWidth={0}>\n                {gwData.map((g:any,i:number) => <Cell key={i} fill={g.color}/>)}\n              </Pie>\n            </PieChart>\n          </div>\n          <div style={{ display:\"flex\", flexDirection:\"column\", gap:8, marginTop:8 }}>\n            {gwData.map((g:any) => (\n              <div key={g.name} style={{ display:\"flex\", alignItems:\"center\", gap:8 }}>\n                <div style={{ width:8, height:8, borderRadius:\"50%\", background:g.color, flexShrink:0 }}/>\n                <span style={{ fontSize:12, color:\"rgba(255,255,255,0.6)\", flex:1 }}>{g.name}</span>\n                <span style={{ fontSize:12, fontWeight:700, color:\"#fff\" }}>{g.value}{typeof g.value===\"number\"&&g.value<100?\"%\":\"\"}</span>\n              </div>\n            ))}\n          </div>\n        </motion.div>\n      </div>\n\n      {/* Recent users */}\n      <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.5}}\n        style={{ padding:20, borderRadius:16, background:\"rgba(255,255,255,0.03)\", border:\"1px solid rgba(255,255,255,0.06)\" }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:16 }}>\n          <p style={{ fontSize:14, fontWeight:700, color:\"#fff\", margin:0 }}>Recent Signups</p>\n          <Link href=\"/admin/users\" style={{ display:\"flex\", alignItems:\"center\", gap:4, fontSize:12, color:V.v300, textDecoration:\"none\", fontWeight:600 }}>\n            All users <ChevronRight size={12}/>\n          </Link>\n        </div>\n        {recentUsers.length === 0 ? (\n          <p style={{ fontSize:13, color:\"rgba(255,255,255,0.3)\", textAlign:\"center\", padding:\"24px 0\", margin:0 }}>No users yet</p>\n        ) : (\n          <div style={{ display:\"flex\", flexDirection:\"column\", gap:6 }}>\n            {recentUsers.slice(0,5).map((u:any,i:number) => (\n              <motion.div key={u.id} initial={{opacity:0,x:-8}} animate={{opacity:1,x:0}} transition={{delay:0.52+i*0.04}}\n                style={{ display:\"flex\", alignItems:\"center\", gap:12, padding:\"10px 12px\", borderRadius:12, background:\"rgba(255,255,255,0.02)\" }}>\n                <div style={{ width:32, height:32, borderRadius:10, background:`linear-gradient(135deg,${V.v500},${V.v700})`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", fontSize:12, fontWeight:800, color:\"#fff\", flexShrink:0 }}>\n                  {u.name?.charAt(0)||\"U\"}\n                </div>\n                <div style={{ flex:1, minWidth:0 }}>\n                  <p style={{ fontSize:13, fontWeight:600, color:\"rgba(255,255,255,0.8)\", margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{u.name}</p>\n                  <p style={{ fontSize:11, color:\"rgba(255,255,255,0.3)\", margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{u.email}</p>\n                </div>\n                <div style={{ textAlign:\"right\", flexShrink:0 }}>\n                  <span style={{ fontSize:10, fontWeight:700, color:u.status===\"ACTIVE\"?V.green:V.amber, background:u.status===\"ACTIVE\"?\"rgba(16,185,129,0.1)\":\"rgba(245,158,11,0.1)\", padding:\"2px 8px\", borderRadius:99 }}>{u.status}</span>\n                  <p style={{ fontSize:10, color:\"rgba(255,255,255,0.25)\", margin:\"3px 0 0\" }}>{new Date(u.createdAt).toLocaleDateString()}</p>\n                </div>\n                <Link href={`/admin/users/${u.id}`} style={{ textDecoration:\"none\" }}>\n                  <ChevronRight size={14} color=\"rgba(255,255,255,0.2)\"/>\n                </Link>\n              </motion.div>\n            ))}\n          </div>\n        )}\n      </motion.div>\n\n      <style>{`\n        @media(max-width:700px){\n          .admin-charts{grid-template-columns:1fr!important}\n        }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/admin/users/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { motion } from \"framer-motion\";\nimport { Users, UserCheck, Ban, Trash2, ExternalLink } from \"lucide-react\";\nimport Link from \"next/link\";\nimport toast from \"react-hot-toast\";\nimport { PageHeader, FilterBar, SearchInput, SelectFilter, DataTable, Badge, Pagination, StatGrid, StatCard } from \"../../../components/admin/AdminTable\";\n\nconst V = { accent:\"#6B35E8\", v400:\"#8B5CF6\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\nconst STATUS_BG: Record<string,string> = { ACTIVE:\"rgba(16,185,129,0.1)\", PENDING_VERIFICATION:\"rgba(245,158,11,0.1)\", SUSPENDED:\"rgba(239,68,68,0.1)\", BANNED:\"rgba(239,68,68,0.15)\" };\nconst STATUS_C:  Record<string,string> = { ACTIVE:V.green, PENDING_VERIFICATION:V.amber, SUSPENDED:V.red, BANNED:V.red };\nconst PLAN_BG:   Record<string,string> = { FREE:\"rgba(255,255,255,0.07)\", GROWTH:\"rgba(107,53,232,0.12)\", PRO:\"rgba(245,158,11,0.1)\", ENTERPRISE:\"rgba(16,185,129,0.1)\" };\nconst PLAN_C:    Record<string,string> = { FREE:\"rgba(255,255,255,0.4)\", GROWTH:V.accent, PRO:V.amber, ENTERPRISE:V.green };\n\nexport default function AdminUsersPage() {\n  const qc = useQueryClient();\n  const [page, setPage]     = useState(1);\n  const [search, setSearch] = useState(\"\");\n  const [status, setStatus] = useState(\"\");\n  const [plan, setPlan]     = useState(\"\");\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"admin-users\", page, search, status, plan],\n    queryFn:  () => adminAPI.getUsers({ page, limit:20, search, status, plan }).then((r:any) => r.data),\n    placeholderData: (prev:any) => prev,\n  });\n\n  const { data: statsData } = useQuery<any>({\n    queryKey: [\"admin-overview\"],\n    queryFn:  () => adminAPI.getStats().then((r:any) => r.data.data),\n  });\n\n  const deleteMut  = useMutation({\n    mutationFn: (id:string) => adminAPI.deleteUser(id),\n    onSuccess: () => { toast.success(\"User deleted\"); qc.invalidateQueries({ queryKey:[\"admin-users\"] }); },\n    onError:   () => toast.error(\"Delete failed\"),\n  });\n  const suspendMut = useMutation({\n    mutationFn: ({id,s}:{id:string;s:string}) => s===\"SUSPENDED\" ? adminAPI.unbanUser(id) : adminAPI.banUser(id),\n    onSuccess: () => { toast.success(\"Updated\"); qc.invalidateQueries({ queryKey:[\"admin-users\"] }); },\n  });\n\n  const users = data?.data || [];\n  const meta  = data?.meta || data?.pagination || { total:0, page:1, pages:1 };\n  const s     = statsData;\n\n  const rows = users.map((u: any) => ({\n    user: (\n      <div style={{ display:\"flex\", alignItems:\"center\", gap:9, minWidth:0 }}>\n        <div style={{ width:32, height:32, borderRadius:9, background:`linear-gradient(135deg,#2D1B69,#6B35E8)`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", fontSize:12, fontWeight:800, color:\"#fff\", flexShrink:0 }}>\n          {u.name?.charAt(0)||\"U\"}\n        </div>\n        <div style={{ minWidth:0 }}>\n          <Link href={`/admin/users/${u.id}`} style={{ fontSize:13, fontWeight:700, color:\"rgba(255,255,255,0.9)\", textDecoration:\"none\", display:\"block\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>\n            {u.name}\n          </Link>\n          <p style={{ fontSize:10, color:\"rgba(255,255,255,0.4)\", margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{u.email}</p>\n        </div>\n      </div>\n    ),\n    plan:   <Badge label={u.plan||\"FREE\"} color={PLAN_C[u.plan]||PLAN_C.FREE} bg={PLAN_BG[u.plan]||PLAN_BG.FREE}/>,\n    status: <Badge label={u.status||\"ACTIVE\"} color={STATUS_C[u.status]||V.green} bg={STATUS_BG[u.status]||STATUS_BG.ACTIVE}/>,\n    stores: <span style={{ fontSize:13, fontWeight:700, color:\"rgba(255,255,255,0.7)\" }}>{u._count?.stores||0}</span>,\n    joined: <span style={{ fontSize:11, color:\"rgba(255,255,255,0.35)\" }}>{new Date(u.createdAt).toLocaleDateString(\"en-NG\",{day:\"numeric\",month:\"short\",year:\"2-digit\"})}</span>,\n    actions: (\n      <div style={{ display:\"flex\", gap:5 }}>\n        <Link href={`/admin/users/${u.id}`}\n          style={{ padding:\"5px 8px\", borderRadius:7, background:\"rgba(107,53,232,0.1)\", border:\"1px solid rgba(107,53,232,0.2)\", color:\"#A78BFA\", textDecoration:\"none\", display:\"flex\", alignItems:\"center\" }}>\n          <ExternalLink size={11}/>\n        </Link>\n        <button onClick={() => suspendMut.mutate({ id:u.id, s:u.status })}\n          style={{ padding:\"5px 8px\", borderRadius:7, background:u.status===\"SUSPENDED\"?\"rgba(16,185,129,0.1)\":\"rgba(239,68,68,0.07)\", border:`1px solid ${u.status===\"SUSPENDED\"?\"rgba(16,185,129,0.2)\":\"rgba(239,68,68,0.12)\"}`, color:u.status===\"SUSPENDED\"?V.green:V.red, cursor:\"pointer\", display:\"flex\", alignItems:\"center\" }}>\n          {u.status===\"SUSPENDED\" ? <UserCheck size={11}/> : <Ban size={11}/>}\n        </button>\n        <button onClick={() => { if(confirm(`Delete ${u.name}?`)) deleteMut.mutate(u.id); }}\n          style={{ padding:\"5px 8px\", borderRadius:7, background:\"rgba(239,68,68,0.06)\", border:\"1px solid rgba(239,68,68,0.1)\", color:V.red, cursor:\"pointer\", display:\"flex\", alignItems:\"center\" }}>\n          <Trash2 size={11}/>\n        </button>\n      </div>\n    ),\n  }));\n\n  return (\n    <div>\n      <PageHeader title=\"Users\" sub={`${(meta.total||0).toLocaleString()} merchants on the platform`}/>\n\n      <StatGrid cols={4}>\n        <StatCard label=\"Total users\"    value={(s?.users?.total||0).toLocaleString()}     color={V.accent}  icon={Users}/>\n        <StatCard label=\"Active\"         value={(s?.users?.active||0).toLocaleString()}    color={V.green}   icon={UserCheck}/>\n        <StatCard label=\"Suspended\"      value={(s?.users?.suspended||0).toLocaleString()} color={V.red}     icon={Ban}/>\n        <StatCard label=\"This month\"     value={`+${s?.users?.newThisMonth||0}`}           color={V.cyan}    icon={Users}/>\n      </StatGrid>\n\n      <FilterBar>\n        <SearchInput value={search} onChange={v => { setSearch(v); setPage(1); }} placeholder=\"Search by name or email...\"/>\n        <SelectFilter value={status} onChange={v => { setStatus(v); setPage(1); }} options={[\n          { value:\"\", label:\"All status\" },\n          { value:\"ACTIVE\", label:\"Active\" },\n          { value:\"PENDING_VERIFICATION\", label:\"Pending\" },\n          { value:\"SUSPENDED\", label:\"Suspended\" },\n          { value:\"BANNED\", label:\"Banned\" },\n        ]}/>\n        <SelectFilter value={plan} onChange={v => { setPlan(v); setPage(1); }} options={[\n          { value:\"\", label:\"All plans\" },\n          { value:\"FREE\", label:\"Free\" },\n          { value:\"GROWTH\", label:\"Growth\" },\n          { value:\"PRO\", label:\"Pro\" },\n          { value:\"ENTERPRISE\", label:\"Enterprise\" },\n        ]}/>\n      </FilterBar>\n\n      <DataTable\n        loading={isLoading}\n        cols={[\n          { key:\"user\",    label:\"User\",    width:\"2fr\"    },\n          { key:\"plan\",    label:\"Plan\",    width:\"100px\"  },\n          { key:\"status\",  label:\"Status\",  width:\"120px\"  },\n          { key:\"stores\",  label:\"Stores\",  width:\"70px\",  hide:\"sm\" },\n          { key:\"joined\",  label:\"Joined\",  width:\"90px\",  hide:\"md\" },\n          { key:\"actions\", label:\"\",        width:\"110px\"  },\n        ]}\n        rows={rows}\n        empty=\"No users found\"\n      />\n\n      <Pagination page={page} pages={meta.pages||1} total={meta.total||0} onPage={setPage}/>\n    </div>\n  );\n}\n","frontend/src/app/admin/payments/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { CreditCard, TrendingUp, AlertCircle, CheckCircle } from \"lucide-react\";\nimport { PageHeader, FilterBar, SearchInput, SelectFilter, DataTable, Badge, Pagination, StatGrid, StatCard } from \"../../../components/admin/AdminTable\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\n\nfunction fmtNGN(n: number) { return `₦${Number(n||0).toLocaleString()}`; }\n\nexport default function AdminPaymentsPage() {\n  const [page, setPage]       = useState(1);\n  const [gateway, setGateway] = useState(\"\");\n  const [status, setStatus]   = useState(\"\");\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"admin-payments\", page, gateway, status],\n    queryFn: () => adminAPI.get(\"/admin/payments\", { params:{ page, limit:25, gateway, status } }).then((r:any) => r.data),\n  });\n  const { data: stats } = useQuery<any>({\n    queryKey: [\"admin-overview\"],\n    queryFn: () => adminAPI.getStats().then((r:any) => r.data.data),\n  });\n\n  const payments = data?.data || [];\n  const meta     = data?.pagination || { total:0, pages:1 };\n  const s = stats;\n\n  const STATUS_C:  Record<string,string> = { SUCCESS:\"#10B981\", PENDING:\"#F59E0B\", FAILED:\"#EF4444\", REFUNDED:\"rgba(255,255,255,0.4)\" };\n  const STATUS_BG: Record<string,string> = { SUCCESS:\"rgba(16,185,129,0.1)\", PENDING:\"rgba(245,158,11,0.1)\", FAILED:\"rgba(239,68,68,0.1)\", REFUNDED:\"rgba(255,255,255,0.05)\" };\n\n  const rows = payments.map((p: any) => ({\n    ref:     <span style={{ fontSize:12, fontFamily:\"monospace\", color:\"#A78BFA\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\", display:\"block\" }}>{p.reference}</span>,\n    store:   <span style={{ fontSize:12, color:\"rgba(255,255,255,0.7)\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\", display:\"block\" }}>{p.order?.store?.name||\"—\"}</span>,\n    amount:  <span style={{ fontSize:13, fontWeight:700, color:\"rgba(255,255,255,0.9)\" }}>{fmtNGN(p.amount)}</span>,\n    fee:     <span style={{ fontSize:12, color:\"rgba(255,255,255,0.45)\" }}>{fmtNGN(p.platformFee||0)}</span>,\n    gateway: <Badge label={p.gateway||\"—\"} color={p.gateway===\"PAYSTACK\"?V.amber:V.accent} bg={p.gateway===\"PAYSTACK\"?\"rgba(245,158,11,0.1)\":\"rgba(107,53,232,0.1)\"}/>,\n    status:  <Badge label={p.status} color={STATUS_C[p.status]||V.amber} bg={STATUS_BG[p.status]||\"rgba(245,158,11,0.1)\"}/>,\n    date:    <span style={{ fontSize:11, color:\"rgba(255,255,255,0.3)\" }}>{new Date(p.createdAt).toLocaleDateString(\"en-NG\",{day:\"numeric\",month:\"short\"})}</span>,\n  }));\n\n  return (\n    <div>\n      <PageHeader title=\"Payments\" sub={`${(meta.total||0).toLocaleString()} transactions on the platform`}/>\n\n      <StatGrid cols={4}>\n        <StatCard label=\"Total revenue\"   value={fmtNGN(s?.revenue?.total||0)}          color={V.green}  icon={TrendingUp}/>\n        <StatCard label=\"Platform fees\"   value={fmtNGN(s?.fees?.total||0)}              color={V.accent} icon={CreditCard}/>\n        <StatCard label=\"This month\"      value={fmtNGN(s?.revenue?.thisMonth||0)}       color={V.cyan}   icon={CheckCircle}/>\n        <StatCard label=\"Failed payments\" value={(s?.failedPayments||0).toLocaleString()} color={V.red}   icon={AlertCircle}/>\n      </StatGrid>\n\n      <FilterBar>\n        <SelectFilter value={gateway} onChange={v => { setGateway(v); setPage(1); }} options={[\n          { value:\"\", label:\"All gateways\" },\n          { value:\"PAYSTACK\", label:\"Paystack\" },\n          { value:\"STRIPE\", label:\"Stripe\" },\n        ]}/>\n        <SelectFilter value={status} onChange={v => { setStatus(v); setPage(1); }} options={[\n          { value:\"\", label:\"All status\" },\n          { value:\"SUCCESS\", label:\"Success\" },\n          { value:\"PENDING\", label:\"Pending\" },\n          { value:\"FAILED\", label:\"Failed\" },\n          { value:\"REFUNDED\", label:\"Refunded\" },\n        ]}/>\n      </FilterBar>\n\n      <DataTable\n        loading={isLoading}\n        cols={[\n          { key:\"ref\",     label:\"Reference\",  width:\"1.8fr\" },\n          { key:\"store\",   label:\"Store\",       width:\"1fr\",   hide:\"sm\" },\n          { key:\"amount\",  label:\"Amount\",      width:\"100px\" },\n          { key:\"fee\",     label:\"Fee\",         width:\"80px\",  hide:\"md\" },\n          { key:\"gateway\", label:\"Gateway\",     width:\"90px\",  hide:\"sm\" },\n          { key:\"status\",  label:\"Status\",      width:\"90px\"  },\n          { key:\"date\",    label:\"Date\",        width:\"80px\",  hide:\"md\" },\n        ]}\n        rows={rows}\n        empty=\"No payments found\"\n      />\n      <Pagination page={page} pages={meta.pages||1} total={meta.total||0} onPage={setPage}/>\n    </div>\n  );\n}\n","frontend/src/app/admin/analytics/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { AreaChart, Area, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from \"recharts\";\nimport { TrendingUp, Users, ShoppingCart, DollarSign } from \"lucide-react\";\nimport { PageHeader, StatGrid, StatCard } from \"../../../components/admin/AdminTable\";\n\nconst V = { accent:\"#6B35E8\", v400:\"#8B5CF6\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\nconst t = { card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\" };\nconst fmt = (n: number) => `₦${(n/1000).toFixed(0)}k`;\n\nexport default function AdminAnalyticsPage() {\n  const [period, setPeriod] = useState(\"30d\");\n\n  const { data: stats } = useQuery<any>({\n    queryKey: [\"admin-overview\"], queryFn: () => adminAPI.getStats().then((r:any) => r.data.data),\n  });\n  const { data: analytics } = useQuery<any>({\n    queryKey: [\"admin-analytics\", period],\n    queryFn: () => adminAPI.get(\"/admin/analytics\", { params:{ period } }).then((r:any) => r.data.data),\n  });\n\n  const s = stats;\n  const revenueData = s?.monthlyRevenue || [];\n\n  return (\n    <div>\n      <PageHeader title=\"Analytics\" sub=\"Platform-wide performance metrics\"\n        action={\n          <div style={{ display:\"flex\", gap:4, background:\"rgba(255,255,255,0.04)\", borderRadius:10, padding:3 }}>\n            {[\"7d\",\"30d\",\"90d\"].map(p => (\n              <button key={p} onClick={() => setPeriod(p)}\n                style={{ padding:\"5px 12px\", borderRadius:8, border:\"none\", cursor:\"pointer\", fontSize:12, fontWeight:700, fontFamily:\"inherit\", background:period===p?\"rgba(107,53,232,0.2)\":\"transparent\", color:period===p?\"#A78BFA\":\"rgba(255,255,255,0.4)\", transition:\"all 0.15s\" }}>\n                {p}\n              </button>\n            ))}\n          </div>\n        }/>\n\n      <StatGrid cols={4}>\n        <StatCard label=\"Total revenue\"     value={`₦${((s?.revenue?.total||0)/1000000).toFixed(1)}M`} color={V.green}  icon={DollarSign}  sub={s?.revenue?.growth}/>\n        <StatCard label=\"Platform fees\"     value={`₦${((s?.fees?.total||0)/1000).toFixed(0)}k`}       color={V.accent} icon={TrendingUp}/>\n        <StatCard label=\"Active merchants\"  value={(s?.users?.active||0).toLocaleString()}               color={V.cyan}   icon={Users}       sub={s?.users?.growth}/>\n        <StatCard label=\"Total orders\"      value={(s?.orders?.total||0).toLocaleString()}               color={V.amber}  icon={ShoppingCart} sub={s?.orders?.growth}/>\n      </StatGrid>\n\n      {/* Revenue chart */}\n      <div style={{ background:t.card, borderRadius:18, padding:24, border:`1px solid ${t.border}`, marginBottom:16 }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:20 }}>\n          <p style={{ fontSize:14, fontWeight:700, color:t.text, margin:0 }}>Monthly revenue & fees</p>\n        </div>\n        <div style={{ height:220 }}>\n          <ResponsiveContainer width=\"100%\" height=\"100%\">\n            <AreaChart data={revenueData} margin={{ top:0, right:0, left:-20, bottom:0 }}>\n              <defs>\n                <linearGradient id=\"rev\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                  <stop offset=\"5%\"  stopColor={V.accent} stopOpacity={0.3}/>\n                  <stop offset=\"95%\" stopColor={V.accent} stopOpacity={0}/>\n                </linearGradient>\n                <linearGradient id=\"fee\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                  <stop offset=\"5%\"  stopColor={V.green} stopOpacity={0.3}/>\n                  <stop offset=\"95%\" stopColor={V.green} stopOpacity={0}/>\n                </linearGradient>\n              </defs>\n              <XAxis dataKey=\"month\" tick={{ fill:\"rgba(255,255,255,0.3)\", fontSize:11 }} axisLine={false} tickLine={false}/>\n              <YAxis tickFormatter={fmt} tick={{ fill:\"rgba(255,255,255,0.3)\", fontSize:11 }} axisLine={false} tickLine={false}/>\n              <Tooltip contentStyle={{ background:\"#0d0a1a\", border:\"1px solid rgba(255,255,255,0.1)\", borderRadius:10, fontSize:12 }} formatter={(v:any)=>[`₦${Number(v).toLocaleString()}`,\"\"]}/>\n              <Area type=\"monotone\" dataKey=\"revenue\" stroke={V.accent} fill=\"url(#rev)\" strokeWidth={2} name=\"Revenue\"/>\n              <Area type=\"monotone\" dataKey=\"fees\"    stroke={V.green}  fill=\"url(#fee)\" strokeWidth={2} name=\"DropOS Fees\"/>\n            </AreaChart>\n          </ResponsiveContainer>\n        </div>\n      </div>\n\n      {/* Gateway distribution + Plan breakdown */}\n      <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:12 }} className=\"adm-2col\">\n        {/* Gateway */}\n        <div style={{ background:t.card, borderRadius:18, padding:24, border:`1px solid ${t.border}` }}>\n          <p style={{ fontSize:14, fontWeight:700, color:t.text, margin:\"0 0 18px\" }}>Payment gateways</p>\n          {(s?.gatewayStats||[{gateway:\"PAYSTACK\",_count:{id:0}},{gateway:\"STRIPE\",_count:{id:0}}]).map((g:any) => {\n            const total = (s?.gatewayStats||[]).reduce((a:number,x:any)=>a+(x._count?.id||0),0)||1;\n            const pct = Math.round((g._count?.id||0)/total*100);\n            return (\n              <div key={g.gateway} style={{ marginBottom:14 }}>\n                <div style={{ display:\"flex\", justifyContent:\"space-between\", marginBottom:6 }}>\n                  <span style={{ fontSize:12, color:t.muted }}>{g.gateway}</span>\n                  <span style={{ fontSize:12, fontWeight:700, color:t.text }}>{pct}%</span>\n                </div>\n                <div style={{ height:6, borderRadius:99, background:\"rgba(255,255,255,0.06)\", overflow:\"hidden\" }}>\n                  <div style={{ width:`${pct}%`, height:\"100%\", borderRadius:99, background:g.gateway===\"PAYSTACK\"?V.amber:V.accent }}/>\n                </div>\n              </div>\n            );\n          })}\n        </div>\n\n        {/* Plan breakdown */}\n        <div style={{ background:t.card, borderRadius:18, padding:24, border:`1px solid ${t.border}` }}>\n          <p style={{ fontSize:14, fontWeight:700, color:t.text, margin:\"0 0 18px\" }}>Plan distribution</p>\n          {[\n            { plan:\"FREE\",       color:\"rgba(255,255,255,0.4)\", count:s?.users?.byPlan?.FREE||0 },\n            { plan:\"GROWTH\",     color:V.accent,                count:s?.users?.byPlan?.GROWTH||0 },\n            { plan:\"PRO\",        color:V.amber,                 count:s?.users?.byPlan?.PRO||0 },\n            { plan:\"ENTERPRISE\", color:V.green,                 count:s?.users?.byPlan?.ENTERPRISE||0 },\n          ].map(p => {\n            const total = Math.max(s?.users?.total||1, 1);\n            const pct   = Math.round((p.count/total)*100);\n            return (\n              <div key={p.plan} style={{ marginBottom:14 }}>\n                <div style={{ display:\"flex\", justifyContent:\"space-between\", marginBottom:6 }}>\n                  <span style={{ fontSize:12, color:t.muted }}>{p.plan}</span>\n                  <span style={{ fontSize:12, fontWeight:700, color:t.text }}>{p.count.toLocaleString()}</span>\n                </div>\n                <div style={{ height:6, borderRadius:99, background:\"rgba(255,255,255,0.06)\", overflow:\"hidden\" }}>\n                  <div style={{ width:`${pct||2}%`, height:\"100%\", borderRadius:99, background:p.color }}/>\n                </div>\n              </div>\n            );\n          })}\n        </div>\n      </div>\n\n      <style>{`@media(max-width:640px){ .adm-2col{grid-template-columns:1fr!important;} }`}</style>\n    </div>\n  );\n}\n","frontend/src/app/admin/audit-logs/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { Shield } from \"lucide-react\";\nimport { PageHeader, DataTable, Pagination, FilterBar, SelectFilter, SearchInput } from \"../../../components/admin/AdminTable\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\" };\n\nconst ACTION_C: Record<string,string> = {\n  CREATE:\"#10B981\", UPDATE:\"#6B35E8\", DELETE:\"#EF4444\",\n  LOGIN:\"rgba(255,255,255,0.5)\", PLAN_CHANGE:\"#F59E0B\",\n};\n\nexport default function AdminAuditLogsPage() {\n  const [page, setPage]   = useState(1);\n  const [search, setSearch] = useState(\"\");\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"admin-audit\", page, search],\n    queryFn: () => adminAPI.get(\"/admin/audit-logs\", { params:{ page, limit:25, search } }).then((r:any) => r.data),\n  });\n\n  const logs = data?.data || [];\n  const meta = data?.pagination || { total:0, pages:1 };\n\n  const rows = logs.map((l: any) => ({\n    action: (\n      <span style={{ fontSize:11, fontWeight:700, padding:\"2px 8px\", borderRadius:99, background:`${ACTION_C[l.action]||V.accent}14`, color:ACTION_C[l.action]||V.accent }}>\n        {l.action}\n      </span>\n    ),\n    user:     <span style={{ fontSize:12, color:\"rgba(255,255,255,0.7)\" }}>{l.user?.name||l.user?.email||\"System\"}</span>,\n    resource: <span style={{ fontSize:12, fontFamily:\"monospace\", color:\"rgba(255,255,255,0.5)\" }}>{l.resource}</span>,\n    detail:   <span style={{ fontSize:11, color:\"rgba(255,255,255,0.35)\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\", display:\"block\" }}>{JSON.stringify(l.details||{}).slice(0,60)}</span>,\n    date:     <span style={{ fontSize:11, color:\"rgba(255,255,255,0.3)\", whiteSpace:\"nowrap\" }}>{new Date(l.createdAt).toLocaleString(\"en-NG\",{day:\"numeric\",month:\"short\",hour:\"2-digit\",minute:\"2-digit\"})}</span>,\n  }));\n\n  return (\n    <div>\n      <PageHeader title=\"Audit Logs\" sub={`${(meta.total||0).toLocaleString()} actions recorded`}/>\n\n      <FilterBar>\n        <SearchInput value={search} onChange={v => { setSearch(v); setPage(1); }} placeholder=\"Search logs...\"/>\n      </FilterBar>\n\n      <DataTable\n        loading={isLoading}\n        cols={[\n          { key:\"action\",   label:\"Action\",   width:\"100px\" },\n          { key:\"user\",     label:\"User\",     width:\"1fr\",   hide:\"sm\" },\n          { key:\"resource\", label:\"Resource\", width:\"100px\" },\n          { key:\"detail\",   label:\"Details\",  width:\"2fr\",   hide:\"md\" },\n          { key:\"date\",     label:\"When\",     width:\"130px\"  },\n        ]}\n        rows={rows}\n        empty=\"No audit logs\"\n      />\n      <Pagination page={page} pages={meta.pages||1} total={meta.total||0} onPage={setPage}/>\n    </div>\n  );\n}\n","frontend/src/app/admin/error-logs/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { CheckCircle } from \"lucide-react\";\nimport { PageHeader, DataTable, Pagination, FilterBar, SelectFilter } from \"../../../components/admin/AdminTable\";\nimport toast from \"react-hot-toast\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\" };\n\nexport default function AdminErrorLogsPage() {\n  const qc = useQueryClient();\n  const [page, setPage]     = useState(1);\n  const [resolved, setResolved] = useState(\"\");\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"admin-errors\", page, resolved],\n    queryFn: () => adminAPI.get(\"/admin/error-logs\", { params:{ page, limit:25, resolved } }).then((r:any) => r.data),\n  });\n\n  const resolveMut = useMutation({\n    mutationFn: (id:string) => adminAPI.patch(`/admin/error-logs/${id}/resolve`, {}),\n    onSuccess: () => { toast.success(\"Resolved\"); qc.invalidateQueries({ queryKey:[\"admin-errors\"] }); },\n  });\n\n  const logs = data?.data || [];\n  const meta = data?.pagination || { total:0, pages:1 };\n\n  const rows = logs.map((l: any) => ({\n    level: (\n      <span style={{ fontSize:10, fontWeight:800, padding:\"2px 8px\", borderRadius:99, background:l.level===\"ERROR\"?\"rgba(239,68,68,0.12)\":\"rgba(245,158,11,0.1)\", color:l.level===\"ERROR\"?V.red:V.amber }}>\n        {l.level||\"ERROR\"}\n      </span>\n    ),\n    message: <span style={{ fontSize:12, color:\"rgba(255,255,255,0.7)\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\", display:\"block\" }}>{l.message}</span>,\n    path:    <span style={{ fontSize:11, fontFamily:\"monospace\", color:\"rgba(255,255,255,0.4)\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\", display:\"block\" }}>{l.path||\"—\"}</span>,\n    date:    <span style={{ fontSize:11, color:\"rgba(255,255,255,0.3)\", whiteSpace:\"nowrap\" }}>{new Date(l.createdAt).toLocaleString(\"en-NG\",{day:\"numeric\",month:\"short\",hour:\"2-digit\",minute:\"2-digit\"})}</span>,\n    action: !l.resolved && (\n      <button onClick={() => resolveMut.mutate(l.id)}\n        style={{ display:\"flex\", alignItems:\"center\", gap:5, padding:\"5px 10px\", borderRadius:8, border:\"1px solid rgba(16,185,129,0.2)\", background:\"rgba(16,185,129,0.08)\", color:V.green, cursor:\"pointer\", fontSize:11, fontWeight:700, fontFamily:\"inherit\" }}>\n        <CheckCircle size={11}/> Resolve\n      </button>\n    ),\n  }));\n\n  return (\n    <div>\n      <PageHeader title=\"Error Logs\" sub={`${(meta.total||0).toLocaleString()} total errors`}/>\n\n      <FilterBar>\n        <SelectFilter value={resolved} onChange={v => { setResolved(v); setPage(1); }} options={[\n          { value:\"\", label:\"All errors\" },\n          { value:\"false\", label:\"Unresolved\" },\n          { value:\"true\", label:\"Resolved\" },\n        ]}/>\n      </FilterBar>\n\n      <DataTable\n        loading={isLoading}\n        cols={[\n          { key:\"level\",   label:\"Level\",   width:\"80px\"  },\n          { key:\"message\", label:\"Message\", width:\"2fr\"   },\n          { key:\"path\",    label:\"Path\",    width:\"1fr\",  hide:\"md\" },\n          { key:\"date\",    label:\"When\",    width:\"120px\", hide:\"sm\" },\n          { key:\"action\",  label:\"\",        width:\"100px\" },\n        ]}\n        rows={rows}\n        empty=\"No error logs\"\n      />\n      <Pagination page={page} pages={meta.pages||1} total={meta.total||0} onPage={setPage}/>\n    </div>\n  );\n}\n","frontend/src/app/admin/settings/page.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { useQuery, useMutation } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { PageHeader } from \"../../../components/admin/AdminTable\";\nimport { motion } from \"framer-motion\";\nimport { Save, Globe, DollarSign, Bell, Shield, Percent } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\" };\nconst t = { card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\", input:\"rgba(255,255,255,0.05)\" };\nconst inp = { width:\"100%\", padding:\"10px 14px\", borderRadius:11, border:`1px solid rgba(255,255,255,0.09)`, background:\"rgba(255,255,255,0.05)\", color:\"rgba(255,255,255,0.9)\", fontSize:13, fontFamily:\"inherit\", outline:\"none\" };\n\nexport default function AdminSettingsPage() {\n  const { data: raw } = useQuery<any>({\n    queryKey: [\"admin-settings\"],\n    queryFn: () => adminAPI.getSettings().then((r:any) => r.data.data),\n  });\n\n  const [form, setForm] = useState({\n    platformName:         \"DropOS\",\n    platformFeePercent:   \"2\",\n    supportEmail:         \"support@droposhq.com\",\n    maintenanceMode:      false,\n    registrationEnabled:  true,\n    defaultPlan:          \"FREE\",\n    maxStoresPerUser:     \"5\",\n    maxProductsPerStore:  \"1000\",\n  });\n\n  useEffect(() => {\n    if (!raw) return;\n    const map: any = {};\n    (Array.isArray(raw) ? raw : []).forEach((s: any) => { map[s.key] = s.value; });\n    setForm(prev => ({\n      ...prev,\n      platformName:         map.platformName         || prev.platformName,\n      platformFeePercent:   map.platformFeePercent   || prev.platformFeePercent,\n      supportEmail:         map.supportEmail         || prev.supportEmail,\n      maintenanceMode:      map.maintenanceMode      === \"true\",\n      registrationEnabled:  map.registrationEnabled  !== \"false\",\n      defaultPlan:          map.defaultPlan          || prev.defaultPlan,\n      maxStoresPerUser:     map.maxStoresPerUser     || prev.maxStoresPerUser,\n      maxProductsPerStore:  map.maxProductsPerStore  || prev.maxProductsPerStore,\n    }));\n  }, [raw]);\n\n  const saveMut = useMutation({\n    mutationFn: () => adminAPI.updateSettings(form),\n    onSuccess: () => toast.success(\"Settings saved\"),\n    onError:   () => toast.error(\"Save failed\"),\n  });\n\n  const Field = ({ label, desc, children }: any) => (\n    <div style={{ paddingBottom:18, marginBottom:18, borderBottom:`1px solid rgba(255,255,255,0.05)` }}>\n      <label style={{ display:\"block\", fontSize:12, fontWeight:700, color:t.muted, marginBottom:4 }}>{label}</label>\n      {desc && <p style={{ fontSize:11, color:\"rgba(255,255,255,0.25)\", margin:\"0 0 8px\", lineHeight:1.4 }}>{desc}</p>}\n      {children}\n    </div>\n  );\n\n  const Toggle = ({ val, onChange, label, desc }: any) => (\n    <Field label={label} desc={desc}>\n      <button onClick={() => onChange(!val)}\n        style={{ width:44, height:24, borderRadius:12, border:\"none\", cursor:\"pointer\", background:val?V.accent:\"rgba(255,255,255,0.1)\", position:\"relative\", padding:0, transition:\"background 0.2s\" }}>\n        <div style={{ position:\"absolute\", top:3, left:val?23:3, width:18, height:18, borderRadius:\"50%\", background:\"#fff\", transition:\"left 0.2s\", boxShadow:\"0 1px 4px rgba(0,0,0,0.3)\" }}/>\n      </button>\n      <span style={{ marginLeft:10, fontSize:13, color:val?V.green:t.muted, fontWeight:600 }}>{val?\"On\":\"Off\"}</span>\n    </Field>\n  );\n\n  const sections = [\n    { icon:Globe, color:V.accent, title:\"Platform\", fields: (\n      <>\n        <Field label=\"Platform name\"><input value={form.platformName} onChange={e=>setForm(f=>({...f,platformName:e.target.value}))} style={inp}/></Field>\n        <Field label=\"Support email\"><input type=\"email\" value={form.supportEmail} onChange={e=>setForm(f=>({...f,supportEmail:e.target.value}))} style={inp}/></Field>\n      </>\n    )},\n    { icon:Percent, color:V.amber, title:\"Billing\", fields: (\n      <>\n        <Field label=\"Transaction fee (%)\" desc=\"Percentage DropOS takes from each order on Free plan\">\n          <input type=\"number\" value={form.platformFeePercent} onChange={e=>setForm(f=>({...f,platformFeePercent:e.target.value}))} min=\"0\" max=\"100\" style={inp}/>\n        </Field>\n        <Field label=\"Default plan for new users\">\n          <select value={form.defaultPlan} onChange={e=>setForm(f=>({...f,defaultPlan:e.target.value}))} style={{ ...inp }}>\n            <option value=\"FREE\">Free</option><option value=\"GROWTH\">Growth</option><option value=\"PRO\">Pro</option>\n          </select>\n        </Field>\n      </>\n    )},\n    { icon:Shield, color:V.red, title:\"Limits\", fields: (\n      <>\n        <Field label=\"Max stores per user\"><input type=\"number\" value={form.maxStoresPerUser} onChange={e=>setForm(f=>({...f,maxStoresPerUser:e.target.value}))} style={inp}/></Field>\n        <Field label=\"Max products per store\"><input type=\"number\" value={form.maxProductsPerStore} onChange={e=>setForm(f=>({...f,maxProductsPerStore:e.target.value}))} style={inp}/></Field>\n      </>\n    )},\n    { icon:Bell, color:V.green, title:\"Status\", fields: (\n      <>\n        <Toggle val={form.maintenanceMode} onChange={(v:boolean)=>setForm(f=>({...f,maintenanceMode:v}))} label=\"Maintenance mode\" desc=\"Shows maintenance banner on all storefronts\"/>\n        <Toggle val={form.registrationEnabled} onChange={(v:boolean)=>setForm(f=>({...f,registrationEnabled:v}))} label=\"New registrations\" desc=\"Allow new users to sign up\"/>\n      </>\n    )},\n  ];\n\n  return (\n    <div style={{ maxWidth:640 }}>\n      <PageHeader title=\"Platform Settings\" sub=\"Core configuration for the DropOS platform\"\n        action={\n          <button onClick={() => saveMut.mutate()} disabled={saveMut.isPending}\n            style={{ display:\"flex\", alignItems:\"center\", gap:6, padding:\"9px 18px\", borderRadius:10, border:\"none\", cursor:\"pointer\", background:V.accent, color:\"#fff\", fontSize:13, fontWeight:700, fontFamily:\"inherit\" }}>\n            <Save size={13}/> {saveMut.isPending?\"Saving...\":\"Save settings\"}\n          </button>\n        }/>\n\n      <div style={{ display:\"flex\", flexDirection:\"column\", gap:12 }}>\n        {sections.map((sec, i) => {\n          const Icon = sec.icon;\n          return (\n            <motion.div key={sec.title} initial={{ opacity:0, y:12 }} animate={{ opacity:1, y:0 }} transition={{ delay:i*0.08 }}\n              style={{ background:t.card, borderRadius:18, padding:\"22px 24px\", border:`1px solid ${t.border}` }}>\n              <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:20, paddingBottom:14, borderBottom:`1px solid rgba(255,255,255,0.05)` }}>\n                <div style={{ width:32, height:32, borderRadius:9, background:`${sec.color}14`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  <Icon size={14} color={sec.color}/>\n                </div>\n                <p style={{ fontSize:13, fontWeight:800, color:t.text, margin:0 }}>{sec.title}</p>\n              </div>\n              {sec.fields}\n            </motion.div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/admin/support/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { MessageSquare, Clock, CheckCircle2, AlertCircle, ChevronDown, ChevronUp } from \"lucide-react\";\nimport { PageHeader, FilterBar, SelectFilter, DataTable, Badge, Pagination, StatGrid, StatCard } from \"../../../components/admin/AdminTable\";\nimport toast from \"react-hot-toast\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\n\nexport default function AdminSupportPage() {\n  const qc = useQueryClient();\n  const [page, setPage]     = useState(1);\n  const [status, setStatus] = useState(\"OPEN\");\n  const [expanded, setExpanded] = useState<string|null>(null);\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"admin-support\", page, status],\n    queryFn: () => adminAPI.get(\"/admin/support\", { params:{ page, limit:20, status } }).then((r:any) => r.data),\n  });\n\n  const tickets = data?.data || [];\n  const meta    = data?.pagination || { total:0, pages:1 };\n  const counts  = data?.counts || { open:0, inProgress:0, resolved:0, total:0 };\n\n  const rows = tickets.map((tk: any) => ({\n    subject: (\n      <div>\n        <p style={{ fontSize:13, fontWeight:700, color:\"rgba(255,255,255,0.9)\", margin:\"0 0 2px\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{tk.subject}</p>\n        {expanded === tk.id && <p style={{ fontSize:12, color:\"rgba(255,255,255,0.5)\", margin:\"6px 0 0\", lineHeight:1.5, whiteSpace:\"normal\" }}>{tk.message}</p>}\n      </div>\n    ),\n    user:    <span style={{ fontSize:12, color:\"rgba(255,255,255,0.6)\", whiteSpace:\"nowrap\" }}>{tk.user?.name||tk.user?.email||\"—\"}</span>,\n    type:    <Badge label={tk.type||\"GENERAL\"} color={V.cyan} bg=\"rgba(6,182,212,0.1)\"/>,\n    status:  <Badge label={tk.status} color={tk.status===\"RESOLVED\"?V.green:tk.status===\"IN_PROGRESS\"?V.amber:V.accent} bg={tk.status===\"RESOLVED\"?\"rgba(16,185,129,0.1)\":tk.status===\"IN_PROGRESS\"?\"rgba(245,158,11,0.1)\":\"rgba(107,53,232,0.1)\"}/>,\n    date:    <span style={{ fontSize:11, color:\"rgba(255,255,255,0.3)\" }}>{new Date(tk.createdAt).toLocaleDateString(\"en-NG\",{day:\"numeric\",month:\"short\"})}</span>,\n    expand:  (\n      <button onClick={() => setExpanded(expanded===tk.id?null:tk.id)}\n        style={{ background:\"none\", border:\"none\", cursor:\"pointer\", color:\"rgba(255,255,255,0.4)\", padding:4 }}>\n        {expanded===tk.id ? <ChevronUp size={13}/> : <ChevronDown size={13}/>}\n      </button>\n    ),\n  }));\n\n  return (\n    <div>\n      <PageHeader title=\"Support\" sub=\"Customer tickets and help requests\"/>\n\n      <StatGrid cols={4}>\n        <StatCard label=\"Open\"        value={counts.open||0}       color={V.red}    icon={AlertCircle}/>\n        <StatCard label=\"In progress\" value={counts.inProgress||0} color={V.amber}  icon={Clock}/>\n        <StatCard label=\"Resolved\"    value={counts.resolved||0}   color={V.green}  icon={CheckCircle2}/>\n        <StatCard label=\"Total\"       value={counts.total||0}       color={V.accent} icon={MessageSquare}/>\n      </StatGrid>\n\n      <FilterBar>\n        <SelectFilter value={status} onChange={v => { setStatus(v); setPage(1); }} options={[\n          { value:\"OPEN\",        label:\"Open\"        },\n          { value:\"IN_PROGRESS\", label:\"In Progress\" },\n          { value:\"RESOLVED\",    label:\"Resolved\"    },\n          { value:\"\",            label:\"All tickets\" },\n        ]}/>\n      </FilterBar>\n\n      <DataTable\n        loading={isLoading}\n        cols={[\n          { key:\"subject\", label:\"Subject\", width:\"2fr\"          },\n          { key:\"user\",    label:\"User\",    width:\"1fr\",  hide:\"sm\" },\n          { key:\"type\",    label:\"Type\",    width:\"100px\",hide:\"md\" },\n          { key:\"status\",  label:\"Status\",  width:\"110px\"          },\n          { key:\"date\",    label:\"Date\",    width:\"80px\", hide:\"sm\" },\n          { key:\"expand\",  label:\"\",        width:\"40px\"           },\n        ]}\n        rows={rows}\n        empty=\"No tickets\"\n      />\n      <Pagination page={page} pages={meta.pages||1} total={meta.total||0} onPage={setPage}/>\n    </div>\n  );\n}\n","frontend/src/app/admin/stores/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { Store, Package, ShoppingCart, Ban, CheckCircle, ExternalLink } from \"lucide-react\";\nimport { PageHeader, FilterBar, SearchInput, SelectFilter, DataTable, Badge, Pagination, StatGrid, StatCard } from \"../../../components/admin/AdminTable\";\nimport toast from \"react-hot-toast\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\n\nexport default function AdminStoresPage() {\n  const qc = useQueryClient();\n  const [page, setPage] = useState(1);\n  const [search, setSearch] = useState(\"\");\n  const [status, setStatus] = useState(\"\");\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"admin-stores\", page, search, status],\n    queryFn: () => adminAPI.get(\"/admin/stores\", { params:{ page, limit:20, search, status } }).then((r:any) => r.data),\n  });\n  const { data: stats } = useQuery<any>({\n    queryKey: [\"admin-overview\"], queryFn: () => adminAPI.getStats().then((r:any) => r.data.data),\n  });\n\n  const updateMut = useMutation({\n    mutationFn: ({ id, data }: any) => adminAPI.patch(`/admin/stores/${id}`, data),\n    onSuccess: () => { toast.success(\"Updated\"); qc.invalidateQueries({ queryKey:[\"admin-stores\"] }); },\n  });\n\n  const stores = data?.data || [];\n  const meta   = data?.pagination || { total:0, pages:1 };\n  const s      = stats;\n\n  const rows = stores.map((st: any) => ({\n    store: (\n      <div style={{ display:\"flex\", alignItems:\"center\", gap:9 }}>\n        <div style={{ width:30, height:30, borderRadius:8, background:`${st.primaryColor||V.accent}18`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0 }}>\n          <Store size={13} color={st.primaryColor||V.accent}/>\n        </div>\n        <div style={{ minWidth:0 }}>\n          <p style={{ fontSize:13, fontWeight:700, color:\"rgba(255,255,255,0.9)\", margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{st.name}</p>\n          <p style={{ fontSize:10, color:\"rgba(255,255,255,0.4)\", margin:0 }}>/{st.slug}</p>\n        </div>\n      </div>\n    ),\n    owner:    <div><p style={{ fontSize:12, color:\"rgba(255,255,255,0.7)\", margin:0 }}>{st.owner?.name}</p><p style={{ fontSize:10, color:\"rgba(255,255,255,0.35)\", margin:0 }}>{st.owner?.email}</p></div>,\n    plan:     <Badge label={st.owner?.plan||\"FREE\"} color={V.accent} bg=\"rgba(107,53,232,0.1)\"/>,\n    products: <span style={{ fontSize:13, fontWeight:700, color:\"rgba(255,255,255,0.7)\" }}>{st._count?.products||0}</span>,\n    orders:   <span style={{ fontSize:13, fontWeight:700, color:\"rgba(255,255,255,0.7)\" }}>{st._count?.orders||0}</span>,\n    status:   <Badge label={st.status||\"ACTIVE\"} color={st.status===\"SUSPENDED\"?V.red:V.green} bg={st.status===\"SUSPENDED\"?\"rgba(239,68,68,0.1)\":\"rgba(16,185,129,0.1)\"}/>,\n    actions: (\n      <div style={{ display:\"flex\", gap:5 }}>\n        <a href={`/store/${st.slug}`} target=\"_blank\" rel=\"noreferrer\"\n          style={{ padding:\"4px 7px\", borderRadius:6, background:\"rgba(255,255,255,0.05)\", border:\"1px solid rgba(255,255,255,0.07)\", color:\"rgba(255,255,255,0.4)\", textDecoration:\"none\", display:\"flex\", alignItems:\"center\" }}>\n          <ExternalLink size={11}/>\n        </a>\n        <button onClick={() => updateMut.mutate({ id:st.id, data:{ status:st.status===\"SUSPENDED\"?\"ACTIVE\":\"SUSPENDED\" } })}\n          style={{ padding:\"4px 7px\", borderRadius:6, background:st.status===\"SUSPENDED\"?\"rgba(16,185,129,0.1)\":\"rgba(239,68,68,0.07)\", border:`1px solid ${st.status===\"SUSPENDED\"?\"rgba(16,185,129,0.2)\":\"rgba(239,68,68,0.12)\"}`, color:st.status===\"SUSPENDED\"?V.green:V.red, cursor:\"pointer\", display:\"flex\", alignItems:\"center\" }}>\n          {st.status===\"SUSPENDED\" ? <CheckCircle size={11}/> : <Ban size={11}/>}\n        </button>\n      </div>\n    ),\n  }));\n\n  return (\n    <div>\n      <PageHeader title=\"Stores\" sub={`${(meta.total||0).toLocaleString()} stores on the platform`}/>\n      <StatGrid cols={3}>\n        <StatCard label=\"Total stores\"  value={(s?.stores?.total||0).toLocaleString()}  color={V.accent} icon={Store}/>\n        <StatCard label=\"Active\"        value={(s?.stores?.active||0).toLocaleString()} color={V.green}  icon={CheckCircle}/>\n        <StatCard label=\"Total orders\"  value={(s?.orders?.total||0).toLocaleString()}  color={V.amber}  icon={ShoppingCart}/>\n      </StatGrid>\n      <FilterBar>\n        <SearchInput value={search} onChange={v => { setSearch(v); setPage(1); }} placeholder=\"Search stores...\"/>\n        <SelectFilter value={status} onChange={v => { setStatus(v); setPage(1); }} options={[\n          { value:\"\", label:\"All status\" }, { value:\"ACTIVE\", label:\"Active\" }, { value:\"SUSPENDED\", label:\"Suspended\" },\n        ]}/>\n      </FilterBar>\n      <DataTable loading={isLoading}\n        cols={[\n          { key:\"store\",    label:\"Store\",    width:\"2fr\"          },\n          { key:\"owner\",    label:\"Owner\",    width:\"1.5fr\", hide:\"sm\" },\n          { key:\"plan\",     label:\"Plan\",     width:\"90px\"         },\n          { key:\"products\", label:\"Products\", width:\"80px\",  hide:\"md\" },\n          { key:\"orders\",   label:\"Orders\",   width:\"70px\",  hide:\"md\" },\n          { key:\"status\",   label:\"Status\",   width:\"100px\"        },\n          { key:\"actions\",  label:\"\",         width:\"80px\"         },\n        ]} rows={rows} empty=\"No stores found\"/>\n      <Pagination page={page} pages={meta.pages||1} total={meta.total||0} onPage={setPage}/>\n    </div>\n  );\n}\n","frontend/src/app/admin/orders/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { ShoppingCart, DollarSign, CheckCircle, Clock } from \"lucide-react\";\nimport { PageHeader, FilterBar, SearchInput, SelectFilter, DataTable, Badge, Pagination, StatGrid, StatCard } from \"../../../components/admin/AdminTable\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\nconst STATUS_C: Record<string,string> = { PENDING:V.amber, PROCESSING:V.cyan, SHIPPED:V.accent, DELIVERED:V.green, CANCELLED:V.red, REFUNDED:\"rgba(255,255,255,0.35)\" };\n\nexport default function AdminOrdersPage() {\n  const [page, setPage] = useState(1);\n  const [search, setSearch] = useState(\"\");\n  const [status, setStatus] = useState(\"\");\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"admin-orders\", page, search, status],\n    queryFn: () => adminAPI.get(\"/admin/orders\", { params:{ page, limit:25, search, status } }).then((r:any) => r.data),\n  });\n  const { data: stats } = useQuery<any>({\n    queryKey: [\"admin-overview\"], queryFn: () => adminAPI.getStats().then((r:any) => r.data.data),\n  });\n\n  const orders = data?.data || [];\n  const meta   = data?.pagination || { total:0, pages:1 };\n  const s      = stats;\n\n  const rows = orders.map((o: any) => ({\n    order:    <span style={{ fontSize:12, fontFamily:\"monospace\", fontWeight:700, color:\"#A78BFA\" }}>#{o.orderNumber}</span>,\n    store:    <span style={{ fontSize:12, color:\"rgba(255,255,255,0.65)\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\", display:\"block\" }}>{o.store?.name||\"—\"}</span>,\n    customer: <div><p style={{ fontSize:12, color:\"rgba(255,255,255,0.8)\", margin:0 }}>{o.customerName||\"—\"}</p><p style={{ fontSize:10, color:\"rgba(255,255,255,0.35)\", margin:0 }}>{o.customerEmail}</p></div>,\n    total:    <span style={{ fontSize:13, fontWeight:700, color:\"rgba(255,255,255,0.9)\" }}>₦{Number(o.total||0).toLocaleString()}</span>,\n    status:   <Badge label={o.status} color={STATUS_C[o.status]||V.amber} bg={`${STATUS_C[o.status]||V.amber}14`}/>,\n    date:     <span style={{ fontSize:11, color:\"rgba(255,255,255,0.3)\", whiteSpace:\"nowrap\" }}>{new Date(o.createdAt).toLocaleDateString(\"en-NG\",{day:\"numeric\",month:\"short\"})}</span>,\n  }));\n\n  return (\n    <div>\n      <PageHeader title=\"Orders\" sub={`${(meta.total||0).toLocaleString()} orders across all stores`}/>\n      <StatGrid cols={4}>\n        <StatCard label=\"Total orders\"     value={(s?.orders?.total||0).toLocaleString()} color={V.accent} icon={ShoppingCart}/>\n        <StatCard label=\"Total revenue\"    value={`₦${((s?.revenue?.total||0)/1000).toFixed(0)}k`} color={V.green} icon={DollarSign}/>\n        <StatCard label=\"Delivered\"        value={(s?.orders?.delivered||0).toLocaleString()} color={V.green} icon={CheckCircle}/>\n        <StatCard label=\"Pending\"          value={(s?.orders?.pending||0).toLocaleString()} color={V.amber} icon={Clock}/>\n      </StatGrid>\n      <FilterBar>\n        <SearchInput value={search} onChange={v => { setSearch(v); setPage(1); }} placeholder=\"Search by order # or email...\"/>\n        <SelectFilter value={status} onChange={v => { setStatus(v); setPage(1); }} options={[\n          { value:\"\", label:\"All status\" },\n          ...[\"PENDING\",\"PROCESSING\",\"SHIPPED\",\"DELIVERED\",\"CANCELLED\",\"REFUNDED\"].map(s=>({ value:s, label:s }))\n        ]}/>\n      </FilterBar>\n      <DataTable loading={isLoading}\n        cols={[\n          { key:\"order\",    label:\"Order\",    width:\"100px\"         },\n          { key:\"store\",    label:\"Store\",    width:\"1fr\",  hide:\"sm\" },\n          { key:\"customer\", label:\"Customer\", width:\"1.5fr\"         },\n          { key:\"total\",    label:\"Total\",    width:\"100px\"         },\n          { key:\"status\",   label:\"Status\",   width:\"110px\"         },\n          { key:\"date\",     label:\"Date\",     width:\"80px\", hide:\"md\" },\n        ]} rows={rows} empty=\"No orders found\"/>\n      <Pagination page={page} pages={meta.pages||1} total={meta.total||0} onPage={setPage}/>\n    </div>\n  );\n}\n","frontend/src/app/admin/broadcast/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useMutation } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { PageHeader } from \"../../../components/admin/AdminTable\";\nimport { motion } from \"framer-motion\";\nimport { Send, Check, Megaphone } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\" };\nconst t = { card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\" };\nconst inp: any = { width:\"100%\", padding:\"11px 14px\", borderRadius:12, border:\"1px solid rgba(255,255,255,0.09)\", background:\"rgba(255,255,255,0.05)\", color:\"rgba(255,255,255,0.9)\", fontSize:13, fontFamily:\"inherit\", outline:\"none\" };\n\nexport default function AdminBroadcastPage() {\n  const [form, setForm] = useState({ title:\"\", message:\"\", type:\"info\", targetPlan:\"\" });\n  const [sent, setSent] = useState(false);\n\n  const sendMut = useMutation({\n    mutationFn: () => adminAPI.post(\"/admin/broadcast\", form),\n    onSuccess: (res:any) => { toast.success(res.data?.message||\"Sent!\"); setSent(true); setTimeout(()=>{ setSent(false); setForm({ title:\"\", message:\"\", type:\"info\", targetPlan:\"\" }); },3000); },\n    onError: () => toast.error(\"Failed to send\"),\n  });\n\n  return (\n    <div style={{ maxWidth:640 }}>\n      <PageHeader title=\"Broadcast\" sub=\"Send in-app notifications to all or targeted users\"/>\n      <motion.div initial={{ opacity:0,y:12 }} animate={{ opacity:1,y:0 }}\n        style={{ background:t.card, borderRadius:20, padding:28, border:`1px solid ${t.border}`, display:\"flex\", flexDirection:\"column\", gap:16 }}>\n        <div>\n          <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:7 }}>Type</label>\n          <div style={{ display:\"flex\", gap:7, flexWrap:\"wrap\" }}>\n            {[\"info\",\"success\",\"warning\",\"error\"].map(tp => (\n              <button key={tp} onClick={() => setForm(f=>({...f,type:tp}))}\n                style={{ padding:\"6px 14px\", borderRadius:8, border:`1px solid ${form.type===tp?\"rgba(107,53,232,0.4)\":\"rgba(255,255,255,0.08)\"}`, background:form.type===tp?\"rgba(107,53,232,0.1)\":\"transparent\", color:form.type===tp?\"#A78BFA\":t.muted, cursor:\"pointer\", fontSize:12, fontWeight:700, fontFamily:\"inherit\", textTransform:\"capitalize\" }}>\n                {tp}\n              </button>\n            ))}\n          </div>\n        </div>\n        <div>\n          <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:7 }}>Target</label>\n          <select value={form.targetPlan} onChange={e=>setForm(f=>({...f,targetPlan:e.target.value}))} style={inp}>\n            <option value=\"\">All users</option>\n            <option value=\"FREE\">Free plan only</option>\n            <option value=\"GROWTH\">Growth plan only</option>\n            <option value=\"PRO\">Pro plan only</option>\n          </select>\n        </div>\n        <div>\n          <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:7 }}>Title</label>\n          <input value={form.title} onChange={e=>setForm(f=>({...f,title:e.target.value}))} placeholder=\"Notification title\" style={inp}/>\n        </div>\n        <div>\n          <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:7 }}>Message</label>\n          <textarea value={form.message} onChange={e=>setForm(f=>({...f,message:e.target.value}))} placeholder=\"Write your message...\" rows={5} style={{ ...inp, resize:\"vertical\" }}/>\n        </div>\n        {form.title && form.message && (\n          <div style={{ padding:14, borderRadius:12, background:\"rgba(107,53,232,0.06)\", border:\"1px solid rgba(107,53,232,0.15)\", display:\"flex\", gap:10 }}>\n            <Megaphone size={16} color=\"#A78BFA\" style={{ flexShrink:0, marginTop:1 }}/>\n            <div><p style={{ fontSize:13, fontWeight:700, color:t.text, margin:\"0 0 3px\" }}>{form.title}</p><p style={{ fontSize:12, color:t.muted, margin:0 }}>{form.message}</p></div>\n          </div>\n        )}\n        <button onClick={() => sendMut.mutate()} disabled={!form.title||!form.message||sendMut.isPending}\n          style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:8, padding:\"13px 0\", borderRadius:12, border:\"none\", cursor:\"pointer\", background:sent?\"rgba(16,185,129,0.15)\":V.accent, color:\"#fff\", fontSize:14, fontWeight:700, fontFamily:\"inherit\", opacity:(!form.title||!form.message)?0.5:1, transition:\"all 0.2s\" }}>\n          {sent?<><Check size={15}/> Sent!</>:sendMut.isPending?\"Sending...\":<><Send size={14}/> Send broadcast</>}\n        </button>\n      </motion.div>\n    </div>\n  );\n}\n","frontend/src/app/admin/flags/page.tsx":"\"use client\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { PageHeader } from \"../../../components/admin/AdminTable\";\nimport { motion } from \"framer-motion\";\nimport { Flag, RefreshCw } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\" };\nconst t = { card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\" };\n\nconst FLAGS = [\n  { key:\"kiro_enabled\",         label:\"KIRO AI\",                  desc:\"Enable/disable KIRO AI for all merchants\" },\n  { key:\"store_generator\",      label:\"AI Store Generator\",        desc:\"Merchants can use KIRO to auto-generate store identity\" },\n  { key:\"virtual_accounts\",     label:\"Virtual Bank Accounts\",     desc:\"Paystack DVA feature — requires CAC + verified business\" },\n  { key:\"delivery_booking\",     label:\"Delivery Booking\",          desc:\"GIG Logistics + Kwik rider booking from dashboard\" },\n  { key:\"affiliate_program\",    label:\"Affiliate Programme\",       desc:\"20% referral commissions for Pro plan users\" },\n  { key:\"tiktok_shop_sync\",     label:\"TikTok Shop Sync\",          desc:\"Auto-sync products to TikTok Shop\" },\n  { key:\"competitor_spy\",       label:\"Competitor Spy\",            desc:\"AI competitor product research tool\" },\n  { key:\"maintenance_mode\",     label:\"Maintenance Mode\",          desc:\"Show maintenance banner on all storefronts\" },\n  { key:\"new_user_registration\",label:\"New Registrations\",         desc:\"Allow new merchants to sign up\" },\n];\n\nexport default function AdminFlagsPage() {\n  const qc = useQueryClient();\n  const { data:flags={}, isLoading } = useQuery<any>({\n    queryKey: [\"admin-flags\"],\n    queryFn: () => adminAPI.get(\"/admin/feature-flags\").then((r:any) => r.data.data||{}),\n  });\n  const updateMut = useMutation({\n    mutationFn: ({ flag, enabled }:any) => adminAPI.patch(\"/admin/feature-flags\", { flag, enabled }),\n    onSuccess: (_,vars) => { toast.success(`${vars.flag} ${vars.enabled?\"enabled\":\"disabled\"}`); qc.invalidateQueries({ queryKey:[\"admin-flags\"] }); },\n  });\n\n  return (\n    <div style={{ maxWidth:640 }}>\n      <PageHeader title=\"Feature Flags\" sub=\"Toggle features on/off across the entire platform\"/>\n      <div style={{ background:t.card, borderRadius:18, border:`1px solid ${t.border}`, overflow:\"hidden\" }}>\n        {FLAGS.map((flag, i) => {\n          const on = flags[flag.key]===true||flags[flag.key]===\"true\";\n          return (\n            <motion.div key={flag.key} initial={{ opacity:0 }} animate={{ opacity:1 }} transition={{ delay:i*0.04 }}\n              style={{ display:\"flex\", alignItems:\"center\", gap:14, padding:\"15px 20px\", borderBottom:i<FLAGS.length-1?\"1px solid rgba(255,255,255,0.04)\":\"none\" }}>\n              <div style={{ width:32, height:32, borderRadius:9, background:on?\"rgba(16,185,129,0.1)\":\"rgba(255,255,255,0.04)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0, transition:\"background 0.2s\" }}>\n                <Flag size={13} color={on?V.green:\"rgba(255,255,255,0.25)\"}/>\n              </div>\n              <div style={{ flex:1 }}>\n                <p style={{ fontSize:13, fontWeight:700, color:t.text, margin:0 }}>{flag.label}</p>\n                <p style={{ fontSize:11, color:t.muted, margin:\"2px 0 0\", lineHeight:1.4 }}>{flag.desc}</p>\n              </div>\n              {isLoading || updateMut.isPending ? (\n                <RefreshCw size={13} color={t.muted} style={{ animation:\"spin 0.7s linear infinite\", flexShrink:0 }}/>\n              ) : (\n                <button onClick={() => updateMut.mutate({ flag:flag.key, enabled:!on })}\n                  style={{ width:46, height:24, borderRadius:12, border:\"none\", cursor:\"pointer\", background:on?V.accent:\"rgba(255,255,255,0.1)\", position:\"relative\", padding:0, flexShrink:0, transition:\"background 0.2s\" }}>\n                  <div style={{ position:\"absolute\", top:3, left:on?25:3, width:18, height:18, borderRadius:\"50%\", background:\"#fff\", transition:\"left 0.2s\", boxShadow:\"0 1px 4px rgba(0,0,0,0.3)\" }}/>\n                </button>\n              )}\n            </motion.div>\n          );\n        })}\n      </div>\n      <style>{\"@keyframes spin{to{transform:rotate(360deg)}}\"}</style>\n    </div>\n  );\n}\n","backend/src/controllers/admin.controller.ts":"// src/controllers/admin.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { paginate, sanitizeUser } from \"../utils/helpers\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport bcrypt from \"bcryptjs\";\n\n// ── Dashboard Stats ───────────────────────────────────────────────────────────\nexport const getDashboardStats = async (_req: AuthRequest, res: Response) => {\n  const [\n    totalUsers, activeUsers, suspendedUsers,\n    totalStores, activeStores,\n    totalOrders, totalRevenue, platformFees,\n    failedPayments, openTickets,\n    newUsersThisMonth, revenueThisMonth,\n  ] = await Promise.all([\n    await prisma.user.count({ where: { role: \"STORE_OWNER\" } }),\n    await prisma.user.count({ where: { role: \"STORE_OWNER\", status: \"ACTIVE\" } }),\n    await prisma.user.count({ where: { role: \"STORE_OWNER\", status: \"SUSPENDED\" } }),\n    await prisma.store.count(),\n    await prisma.store.count({ where: { status: \"ACTIVE\" } }),\n    await prisma.order.count(),\n    await prisma.payment.aggregate({ where: { status: \"SUCCESS\" }, _sum: { amount: true } }),\n    await prisma.payment.aggregate({ where: { status: \"SUCCESS\" }, _sum: { platformFee: true } }),\n    await prisma.payment.count({ where: { status: \"FAILED\" } }),\n    await prisma.supportTicket.count({ where: { status: { in: [\"OPEN\",\"IN_PROGRESS\"] } } }),\n    await prisma.user.count({\n      where: {\n        role: \"STORE_OWNER\",\n        createdAt: { gte: new Date(new Date().getFullYear(), new Date().getMonth(), 1) },\n      },\n    }),\n    await prisma.payment.aggregate({\n      where: {\n        status: \"SUCCESS\",\n        createdAt: { gte: new Date(new Date().getFullYear(), new Date().getMonth(), 1) },\n      },\n      _sum: { amount: true },\n    }),\n  ]);\n\n  // Monthly revenue for last 7 months\n  const months = Array.from({ length: 7 }, (_, i) => {\n    const d = new Date();\n    d.setMonth(d.getMonth() - (6 - i));\n    return new Date(d.getFullYear(), d.getMonth(), 1);\n  });\n\n  const monthlyRevenue = await Promise.all(\n    months.map(async (start) => {\n      const end = new Date(start.getFullYear(), start.getMonth() + 1, 0);\n      const agg = await prisma.payment.aggregate({\n        where: { status: \"SUCCESS\", createdAt: { gte: start, lte: end } },\n        _sum:  { amount: true, platformFee: true },\n      });\n      return {\n        month:    start.toLocaleString(\"default\", { month: \"short\" }),\n        revenue:  agg._sum.amount || 0,\n        fees:     agg._sum.platformFee || 0,\n      };\n    })\n  );\n\n  // Gateway distribution\n  const gatewayStats = await prisma.payment.groupBy({\n    by:    [\"gateway\"],\n    where: { status: \"SUCCESS\" },\n    _sum:  { amount: true },\n    _count:{ id: true },\n  });\n\n  return res.json({\n    success: true,\n    data: {\n      users:         { total: totalUsers, active: activeUsers, suspended: suspendedUsers, newThisMonth: newUsersThisMonth },\n      stores:        { total: totalStores, active: activeStores },\n      orders:        { total: totalOrders },\n      revenue:       { total: totalRevenue._sum.amount || 0, thisMonth: revenueThisMonth._sum.amount || 0 },\n      platformFees:  { total: platformFees._sum.platformFee || 0 },\n      failedPayments,\n      openTickets,\n      monthlyRevenue,\n      gatewayStats,\n    },\n  });\n};\n\n// ── Get All Users ─────────────────────────────────────────────────────────────\nexport const getAllUsers = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20, status, plan, search, role } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const where: any = {};\n  if (role)   where.role   = role;\n  if (status) where.status = status;\n  if (search) where.OR = [\n    { name:  { contains: search as string, mode: \"insensitive\" } },\n    { email: { contains: search as string, mode: \"insensitive\" } },\n  ];\n\n  if (plan) where.subscription = { plan };\n\n  const [users, total] = await Promise.all([\n    await prisma.user.findMany({\n      where, take, skip,\n      include: {\n        subscription: true,\n        stores: {\n          select: { id: true, name: true, status: true, _count: { select: { orders: true } } },\n        },\n        _count: { select: { stores: true, supportTickets: true } },\n      },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.user.count({ where }),\n  ]);\n\n  // Attach total revenue per user\n  const usersWithRevenue = await Promise.all(\n    users.map(async (user) => {\n      const revenue = await prisma.payment.aggregate({\n        where: { storeId: { in: user.stores.map((s) => s.id) }, status: \"SUCCESS\" },\n        _sum:  { amount: true, platformFee: true, storeEarnings: true },\n      });\n      return {\n        ...sanitizeUser(user),\n        revenue: {\n          total:         revenue._sum.amount || 0,\n          platformFees:  revenue._sum.platformFee || 0,\n          storeEarnings: revenue._sum.storeEarnings || 0,\n        },\n      };\n    })\n  );\n\n  return res.json({\n    success: true,\n    data: usersWithRevenue,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// ── Get Single User (full detail) ─────────────────────────────────────────────\nexport const getUserDetail = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const user = await prisma.user.findUnique({\n    where: { id: userId },\n    include: {\n      subscription: true,\n      stores: {\n        include: {\n          _count:  { select: { products: true, orders: true, customers: true } },\n          payments:{ where: { status: \"SUCCESS\" }, select: { amount: true, platformFee: true, storeEarnings: true } },\n        },\n      },\n      supportTickets: { orderBy: { createdAt: \"desc\" }, take: 5 },\n      _count: { select: { stores: true, supportTickets: true } },\n    },\n  });\n  if (!user) throw new AppError(\"User not found\", 404);\n\n  const totalRevenue = await prisma.payment.aggregate({\n    where: { storeId: { in: user.stores.map((s) => s.id) }, status: \"SUCCESS\" },\n    _sum:  { amount: true, platformFee: true, storeEarnings: true },\n  });\n\n  return res.json({\n    success: true,\n    data: {\n      ...sanitizeUser(user),\n      totalRevenue: totalRevenue._sum.amount     || 0,\n      platformFees: totalRevenue._sum.platformFee|| 0,\n      payouts:      totalRevenue._sum.storeEarnings || 0,\n    },\n  });\n};\n\n// ── Update User ───────────────────────────────────────────────────────────────\nexport const updateUser = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const schema = z.object({\n    name:          z.string().min(2).optional(),\n    email:         z.string().email().optional(),\n    phone:         z.string().optional(),\n    status:        z.enum([\"ACTIVE\",\"SUSPENDED\",\"BANNED\"]).optional(),\n    emailVerified: z.boolean().optional(),\n    twoFAEnabled:  z.boolean().optional(),\n    adminNotes:    z.string().optional(),\n    flags:         z.array(z.string()).optional(),\n    country:       z.string().optional(),\n    city:          z.string().optional(),\n    role:          z.enum([\"STORE_OWNER\",\"SUPER_ADMIN\"]).optional(),\n  });\n\n  const data = schema.parse(req.body);\n  const user = await prisma.user.update({ where: { id: userId }, data });\n\n  // Audit log\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_USER\",\n      entity:   \"User\",\n      entityId: userId,\n      newValues: data as any,\n    },\n  });\n\n  return res.json({ success: true, message: \"User updated\", data: sanitizeUser(user) });\n};\n\n// ── Update Subscription ───────────────────────────────────────────────────────\nexport const updateUserSubscription = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const schema = z.object({\n    plan:            z.enum([\"STARTER\",\"PRO\",\"ADVANCED\"]),\n    status:          z.enum([\"ACTIVE\",\"CANCELLED\",\"EXPIRED\",\"PAST_DUE\"]).optional(),\n    currentPeriodEnd:z.string().optional(),\n  });\n  const data = schema.parse(req.body);\n\n  const sub = await prisma.subscription.update({\n    where: { userId },\n    data:  {\n      plan:   data.plan,\n      status: data.status,\n      ...(data.currentPeriodEnd && { currentPeriodEnd: new Date(data.currentPeriodEnd) }),\n    },\n    include: { user: { select: { email: true, name: true } } },\n  });\n\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_SUBSCRIPTION\",\n      entity:   \"Subscription\",\n      entityId: userId,\n      newValues: data as any,\n    },\n  });\n\n  // Send subscription email\n  try {\n    const { emailService } = await import(\"../services/email.service\");\n    const u = (sub as any).user;\n    const endDate = sub.currentPeriodEnd?.toLocaleDateString(\"en-US\", { year: \"numeric\", month: \"long\", day: \"numeric\" }) || \"N/A\";\n    if (data.status === \"ACTIVE\" || (!data.status && sub.status === \"ACTIVE\")) {\n      emailService.sendSubscriptionStarted(u.email, u.name, data.plan, endDate);\n    } else if (data.status === \"CANCELLED\") {\n      emailService.sendSubscriptionCancelled(u.email, u.name, data.plan, endDate);\n    }\n  } catch {}\n\n  return res.json({ success: true, message: \"Subscription updated\", data: sub });\n};\n\n// ── Delete User ───────────────────────────────────────────────────────────────\nexport const deleteUser = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const user = await prisma.user.findUnique({ where: { id: userId } });\n  if (!user) throw new AppError(\"User not found\", 404);\n  if (user.role === \"SUPER_ADMIN\") throw new AppError(\"Cannot delete super admin\", 403);\n\n  await prisma.user.delete({ where: { id: userId } });\n\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"DELETE_USER\",\n      entity:   \"User\",\n      entityId: userId,\n    },\n  });\n\n  return res.json({ success: true, message: \"User deleted\" });\n};\n\n// ── Platform Settings ─────────────────────────────────────────────────────────\nexport const getSettings = async (_req: AuthRequest, res: Response) => {\n  const settings = await prisma.platformSettings.findUnique({ where: { id: \"singleton\" } });\n  return res.json({ success: true, data: settings });\n};\n\nexport const updateSettings = async (req: AuthRequest, res: Response) => {\n  const schema = z.object({\n    platformFeePercent: z.number().min(0).max(50).optional(),\n    starterPrice:       z.number().optional(),\n    proPrice:           z.number().optional(),\n    advancedPrice:      z.number().optional(),\n    maintenanceMode:    z.boolean().optional(),\n    allowRegistration:  z.boolean().optional(),\n  });\n  const data = schema.parse(req.body);\n\n  const settings = await prisma.platformSettings.update({\n    where: { id: \"singleton\" },\n    data,\n  });\n\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_PLATFORM_SETTINGS\",\n      entity:   \"PlatformSettings\",\n      entityId: \"singleton\",\n      newValues: data as any,\n    },\n  });\n\n  return res.json({ success: true, message: \"Settings updated\", data: settings });\n};\n\n// ── Error Logs ────────────────────────────────────────────────────────────────\nexport const getErrorLogs = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20, resolved } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n  const where: any = {};\n  if (resolved !== undefined) where.resolved = resolved === \"true\";\n\n  const [logs, total] = await Promise.all([\n    await prisma.errorLog.findMany({ where, take, skip, orderBy: { createdAt: \"desc\" } }),\n    await prisma.errorLog.count({ where }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: logs,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\nexport const resolveErrorLog = async (req: AuthRequest, res: Response) => {\n  const { logId } = req.params;\n  await prisma.errorLog.update({ where: { id: logId }, data: { resolved: true } });\n  return res.json({ success: true, message: \"Log resolved\" });\n};\n\n// ── Audit Logs ────────────────────────────────────────────────────────────────\nexport const getAuditLogs = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20 } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const [logs, total] = await Promise.all([\n    await prisma.auditLog.findMany({\n      take, skip,\n      include: { user: { select: { name: true, email: true } } },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.auditLog.count(),\n  ]);\n\n  return res.json({\n    success: true,\n    data: logs,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// ── Platform Analytics ────────────────────────────────────────────────────────\nexport const getPlatformAnalytics = async (req: AuthRequest, res: Response) => {\n  const { period = \"7d\" } = req.query;\n  const days = period === \"30d\" ? 30 : period === \"90d\" ? 90 : 7;\n  const from = new Date();\n  from.setDate(from.getDate() - days);\n\n  const [revenueByDay, ordersByDay, newUsersByDay] = await Promise.all([\n    prisma.payment.groupBy({\n      by: [\"createdAt\"],\n      where: { status: \"SUCCESS\", createdAt: { gte: from } },\n      _sum: { amount: true, platformFee: true },\n    }),\n    prisma.order.groupBy({\n      by: [\"createdAt\"],\n      where: { createdAt: { gte: from } },\n      _count: { id: true },\n    }),\n    prisma.user.groupBy({\n      by: [\"createdAt\"],\n      where: { createdAt: { gte: from }, role: \"STORE_OWNER\" },\n      _count: { id: true },\n    }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: { revenueByDay, ordersByDay, newUsersByDay },\n  });\n};\n","backend/src/routes/admin.routes.ts":"// src/routes/admin.routes.ts\nimport { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  getDashboardStats, getAllUsers, getUserDetail,\n  updateUser, updateUserSubscription, deleteUser,\n  getSettings, updateSettings,\n  getErrorLogs, resolveErrorLog,\n  getAuditLogs, getPlatformAnalytics,\n} from \"../controllers/admin.controller\";\n\nconst router = Router();\n\n// All admin routes require auth + SUPER_ADMIN role\nrouter.use(authenticate);\n\nrouter.get (\"/dashboard\",                 getDashboardStats);\nrouter.get (\"/stats\",                     getDashboardStats); // alias for frontend\nrouter.get (\"/analytics\",                 getPlatformAnalytics);\n\nrouter.get (\"/users\",                     getAllUsers);\nrouter.get (\"/users/:userId\",             getUserDetail);\nrouter.patch(\"/users/:userId\",            updateUser);\nrouter.patch(\"/users/:userId/subscription\", updateUserSubscription);\nrouter.delete(\"/users/:userId\",           deleteUser);\n\nrouter.get (\"/settings\",                  getSettings);\nrouter.patch(\"/settings\",                 updateSettings);\n\nrouter.get (\"/error-logs\",                getErrorLogs);\nrouter.patch(\"/error-logs/:logId/resolve\",resolveErrorLog);\nrouter.get (\"/audit-logs\",                getAuditLogs);\n\nexport default router;\n","frontend/src/lib/api.ts":"\"use client\";\n\n// src/lib/api.ts\nimport axios from \"axios\";\nimport { useAuthStore } from \"../store/auth.store\";\n\nexport const api = axios.create({\n  baseURL:         process.env.NEXT_PUBLIC_API_URL || \"http://localhost:5000/api\",\n  withCredentials: true,\n  headers:         { \"Content-Type\": \"application/json\" },\n  timeout:         30000,\n});\n\n// Public API - no auth, no redirects - for storefront use\nexport const publicApi = axios.create({\n  baseURL:  process.env.NEXT_PUBLIC_API_URL || \"http://localhost:5000/api\",\n  timeout:  30000,\n  headers:  { \"Content-Type\": \"application/json\" },\n});\n\napi.interceptors.request.use((config) => {\n  const token = useAuthStore.getState().accessToken;\n  if (token) config.headers.Authorization = `Bearer ${token}`;\n  \n  // CRITICAL: If sending FormData, delete the default Content-Type\n  // so the browser can set it correctly with the multipart boundary\n  if (config.data instanceof FormData) {\n    delete config.headers[\"Content-Type\"];\n    delete (config.headers as any)[\"content-type\"];\n  }\n  \n  return config;\n});\n\n// ── Refresh lock - prevents race condition ────────────────────\n// Only ONE refresh call happens at a time.\n// All other 401s queue up and wait for it.\nlet isRefreshing = false;\nlet refreshQueue: Array<(token: string) => void> = [];\n\nfunction processQueue(token: string) {\n  refreshQueue.forEach(resolve => resolve(token));\n  refreshQueue = [];\n}\n\n// ── Response interceptor ──────────────────────────────────────\napi.interceptors.response.use(\n  (res) => {\n    // Store refresh token when login succeeds\n    if ((res.config.url?.includes(\"/auth/login\") || res.config.url?.includes(\"/auth/register\")) && res.data?.data?.refreshToken) {\n      if (typeof window !== \"undefined\") {\n        localStorage.setItem(\"dropos-refresh-token\", res.data.data.refreshToken);\n      }\n      // Also set the access token immediately in store\n      if (res.data?.data?.accessToken) {\n        useAuthStore.getState().setAccessToken(res.data.data.accessToken);\n      }\n      // User is set by the mutation's onSuccess handler, not here\n    }\n    return res;\n  },\n  async (err) => {\n    const original = err.config;\n\n    if (err.response?.status !== 401 || original._retry) {\n      return Promise.reject(err);\n    }\n\n    // If already refreshing, queue this request\n    if (isRefreshing) {\n      return new Promise((resolve) => {\n        refreshQueue.push((newToken: string) => {\n          original.headers.Authorization = `Bearer ${newToken}`;\n          resolve(api(original));\n        });\n      });\n    }\n\n    // Mark as retrying so this exact request doesn't loop\n    original._retry = true;\n    isRefreshing = true;\n\n    try {\n      const storedRefreshToken = typeof window !== \"undefined\"\n        ? localStorage.getItem(\"dropos-refresh-token\")\n        : null;\n\n      const { data } = await axios.post(\n        `${process.env.NEXT_PUBLIC_API_URL || \"http://localhost:5000/api\"}/auth/refresh`,\n        { refreshToken: storedRefreshToken },\n        { withCredentials: true }\n      );\n\n      const newToken   = data.data?.accessToken;\n      const newRefresh = data.data?.refreshToken;\n\n      if (!newToken) throw new Error(\"No token in refresh response\");\n\n      // Save new tokens\n      useAuthStore.getState().setAccessToken(newToken);\n      if (newRefresh && typeof window !== \"undefined\") {\n        localStorage.setItem(\"dropos-refresh-token\", newRefresh);\n      }\n\n      // Update default header\n      api.defaults.headers.common[\"Authorization\"] = `Bearer ${newToken}`;\n\n      // Release all queued requests\n      processQueue(newToken);\n\n      // Retry original request\n      original.headers.Authorization = `Bearer ${newToken}`;\n      return api(original);\n\n    } catch (refreshError) {\n      // Refresh truly failed — clear stale token but don't spam redirects\n      refreshQueue = [];\n      isRefreshing = false;\n      if (typeof window !== \"undefined\") {\n        localStorage.removeItem(\"dropos-refresh-token\");\n        // Only redirect if we're actually inside the dashboard (not store or auth pages)\n        const path = window.location.pathname;\n        if (path.startsWith(\"/dashboard\") || path.startsWith(\"/admin\") || path.startsWith(\"/onboarding\")) {\n          useAuthStore.getState().logout();\n          window.location.href = \"/auth/login?expired=1\";\n        }\n      }\n      return Promise.reject(refreshError);\n    } finally {\n      isRefreshing = false;\n    }\n  }\n);\n\n// ── Namespaced API helpers ────────────────────────────────────\nexport const authAPI = {\n  login:           (d: any) => api.post(\"/auth/login\", d),\n  register:        (d: any) => api.post(\"/auth/register\", d),\n  logout:          ()       => api.post(\"/auth/logout\"),\n  getMe:           ()       => api.get(\"/auth/me\"),\n  updateProfile:   (d: any) => api.put(\"/auth/profile\", d),\n  forgotPassword:  (email: string) => api.post(\"/auth/forgot-password\", { email }),\n  resetPassword:   (token: string, password: string) => api.post(\"/auth/reset-password\", { token, password }),\n};\n\nexport const storeAPI = {\n  getAll:    ()           => api.get(\"/stores\"),\n  getOne:    (id: string) => api.get(`/stores/${id}`),\n  create:    (d: any)     => api.post(\"/stores\", d),\n  update:    (id: string, d: any) => api.patch(`/stores/${id}`, d),\n  delete:    (id: string) => api.delete(`/stores/${id}`),\n  getPublic: (slug: string) => publicApi.get(`/stores/public/${slug}`),\n};\n\nexport const productAPI = {\n  getAll:    (storeId: string, p?: any) => api.get(`/products/${storeId}`, { params: p }),\n  getOne:    (storeId: string, id: string) => api.get(`/products/${storeId}/${id}`),\n  create:    (storeId: string, d: any) => api.post(`/products/${storeId}`, d),\n  update:    (storeId: string, id: string, d: any) => api.put(`/products/${storeId}/${id}`, d),\n  delete:    (storeId: string, id: string) => api.delete(`/products/${storeId}/${id}`),\n  getPublicList: (storeId: string, p?: any) => publicApi.get(`/products/public/${storeId}`, { params: p }),\n  getPublicOne:  (storeId: string, id: string) => publicApi.get(`/products/public/${storeId}/${id}`),\n};\n\nexport const orderAPI = {\n  getAll:  (storeId: string, p?: any) => api.get(`/orders/${storeId}`, { params: p }),\n  getOne:  (storeId: string, id: string) => api.get(`/orders/${storeId}/${id}`),\n  create:  (storeId: string, d: any) => publicApi.post(`/orders/${storeId}`, d),\n  update:  (storeId: string, id: string, d: any) => api.patch(`/orders/${storeId}/${id}`, d),\n};\n\nexport const notificationAPI = {\n  getAll:   (p?: any) => api.get(\"/notifications\", { params: p }),\n  getCount: ()        => api.get(\"/notifications/count\"),\n  markRead: (id: string) => api.patch(`/notifications/${id}/read`),\n  markAllRead: ()     => api.patch(\"/notifications/read-all\"),\n};\n\nexport const uploadAPI = {\n  image: async (file: File, folder?: string): Promise<{ success: boolean; data: { url: string; publicId?: string } }> => {\n    const token = useAuthStore.getState().accessToken;\n    const BASE  = (process.env.NEXT_PUBLIC_API_URL || \"http://localhost:5000/api\").replace(/\\/api$/, \"\") + \"/api\";\n    const fd    = new FormData();\n    fd.append(\"image\", file);\n    if (folder) fd.append(\"folder\", folder);\n    const res = await fetch(`${BASE}/upload/image`, {\n      method:  \"POST\",\n      headers: token ? { Authorization: `Bearer ${token}` } : {},\n      body:    fd,\n    });\n    if (!res.ok) {\n      const err = await res.json().catch(() => ({ message: `Upload failed (${res.status})` }));\n      throw new Error(err.message || `Upload failed (${res.status})`);\n    }\n    const json = await res.json();\n    return json;\n  },\n  images: async (files: File[]): Promise<{ data: { data: { urls: string[] } } }> => {\n    const token = useAuthStore.getState().accessToken;\n    const BASE  = (process.env.NEXT_PUBLIC_API_URL || \"http://localhost:5000/api\").replace(/\\/api$/, \"\") + \"/api\";\n    const fd    = new FormData();\n    files.forEach(f => fd.append(\"images\", f));\n    const res = await fetch(`${BASE}/upload/images`, {\n      method:  \"POST\",\n      headers: token ? { Authorization: `Bearer ${token}` } : {},\n      body:    fd,\n    });\n    if (!res.ok) {\n      const err = await res.json().catch(() => ({ message: `Upload failed (${res.status})` }));\n      throw new Error(err.message || `Upload failed (${res.status})`);\n    }\n    return res.json();\n  },\n}\n\nexport const analyticsAPI = {\n  getSummary:  (storeId: string, period?: string) => api.get(`/analytics/${storeId}`, { params: { period } }),\n  getRevenue:  (storeId: string, period?: string) => api.get(`/analytics/${storeId}/revenue`, { params: { period } }),\n  getOrders:   (storeId: string, period?: string) => api.get(`/analytics/${storeId}/orders`, { params: { period } }),\n  getProducts: (storeId: string) => api.get(`/analytics/${storeId}/products`),\n  getCustomers:(storeId: string) => api.get(`/analytics/${storeId}/customers`),\n};\n\nexport const adminAPI = {\n  getStats:           ()                    => api.get(\"/admin/stats\"),\n  getDashboard:       ()                    => api.get(\"/admin/stats\"),\n  getRevenue:         ()                    => api.get(\"/admin/revenue\"),\n  getUsers:           (p?: any)             => api.get(\"/admin/users\", { params: p }),\n  getUser:            (id: string)          => api.get(`/admin/users/${id}`),\n  banUser:            (id: string)          => api.patch(`/admin/users/${id}/ban`),\n  unbanUser:          (id: string)          => api.patch(`/admin/users/${id}/unban`),\n  deleteUser:         (id: string)          => api.delete(`/admin/users/${id}`),\n  updateSubscription: (id: string, d: any)  => api.patch(`/admin/users/${id}/subscription`, d),\n  getAnalytics:       (p?: any)             => api.get(\"/admin/analytics\", { params: p }),\n  getPayments:        (p?: any)             => api.get(\"/admin/payments\",  { params: p }),\n  getTickets:         (p?: any)             => api.get(\"/admin/support\",   { params: p }),\n  updateTicket:       (id: string, d: any)  => api.patch(`/admin/support/${id}`, d),\n  getErrorLogs:       (p?: any)             => api.get(\"/admin/error-logs\",{ params: p }),\n  resolveError:       (id: string)          => api.patch(`/admin/error-logs/${id}/resolve`),\n  getAuditLogs:       (p?: any)             => api.get(\"/admin/audit-logs\",{ params: p }),\n  getSettings:        ()                    => api.get(\"/admin/settings\"),\n  updateSettings:     (d: any)              => api.patch(\"/admin/settings\", d),\n  getWaitlist:        (p?: any)             => api.get(\"/admin/waitlist\",  { params: p }),\n}"};
